    public function get_signature_type($params = array ()) {
        /**
         * Helper method to get signature type from $params or options with fallback to constants
         * @param {array} [$params] parameters that may contain signatureType or signature_type
         * @return {number|null} signature type value
         */
        $signatureTypes = $this->safe_dict($this->options, 'signatureTypes', array());
        $eoaSignatureType = $this->safe_integer($signatureTypes, 'EOA');
        $polyProxySignatureType = $this->safe_integer($signatureTypes, 'POLY_PROXY');
        $polyGnosisSafeSignatureType = $this->safe_integer($signatureTypes, 'POLY_GNOSIS_SAFE');
        // Note => POLY_GNOSIS_SAFE is not supported for now
        $proxyWalletAddress = $this->get_proxy_wallet_address();
        $mainWalletAddress = $this->get_main_wallet_address();
        if ($proxyWalletAddress !== $mainWalletAddress) {
            return $polyProxySignatureType;
        }
        return $eoaSignatureType;
    }

    public function get_side(string $sideString, $params = array ()) {
        /**
         * Helper method to get side from $params or options with fallback to constants
         * Converts BUY/SELL string to integer => BUY = 0, SELL = 1 (matches UtilsBuy/UtilsSell from py-order-utils)
         * @param {string} $sideString side ('BUY' or 'SELL')
         * @param {array} [$params] parameters that may contain side or side_int
         * @return {number} side (0 for BUY, 1 for SELL)
         */
        // Check if side_int is provided directly in $params
        $sideInt = $this->safe_integer($params, 'sideInt') || $this->safe_integer($params, 'side_int');
        if ($sideInt !== null) {
            return $sideInt;
        }
        // Get $sides enum from options
        $sides = $this->safe_dict($this->options, 'sides', array());
        $buySide = $this->safe_integer($sides, 'BUY', 0);
        $sellSide = $this->safe_integer($sides, 'SELL', 1);
        // Convert side string to integer
        $sideUpper = strtoupper($sideString);
        $sideValue = $sellSide; // Default to SELL
        if ($sideUpper === 'BUY') {
            $sideValue = $buySide;
        }
        return $sideValue;
    }

    public function parse_option_type(string $optionType): string {
        return str_replace(' ', '_', strtoupper($this->strip($optionType)));
    }

    public function fetch_markets($params = array ()): array {
        /**
         * retrieves data on all $markets for polymarket
         *
         * @see https://docs.polymarket.com/developers/gamma-$markets-api/fetch-$markets-guide#3-fetch-all-$active-$markets
         *
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @param {boolean} [$params->active] fetch $active $markets only (default => true)
         * @param {boolean} [$params->closed] fetch closed $markets
         * @return {array[]} an array of objects representing $market data
         */
        $limit = 500;
        $options = $this->safe_dict($this->options, 'fetchMarkets', array());
        $request = $this->extend(array(
            'order' => 'id',
            'ascending' => false,
            'limit' => $limit,
            'offset' => 0,
        ), $params);
        $active = $this->safe_bool($options, 'active', true);
        if ($this->safe_value($params, 'closed') === null) {
            $request['closed'] = !$active;
        }
        // Fetch first $page to seed the results
        $firstResponse = $this->gamma_public_get_markets($this->extend(array(), $request, array( 'offset' => 0 )));
        $firstPage = $this->safe_list($firstResponse, 'data', $firstResponse) || array();
        $markets = $firstPage;
        if (strlen($firstPage) >= $limit) {
            // API returns a plain list with no total count — fetch remaining pages in parallel batches.
            // $BATCH_SIZE=10 pages per $round, $MAX_ROUNDS=100 covers up to 500,000 $markets->
            $BATCH_SIZE = 10;
            $MAX_ROUNDS = 100;
            $currentOffset = $limit;
            $done = false;
            for ($round = 0; $round < $MAX_ROUNDS; $round++) {
                $batchPromises = array();
                for ($i = 0; $i < $BATCH_SIZE; $i++) {
                    $batchPromises[] = $this->gamma_public_get_markets($this->extend(array(), $request, array( 'offset' => $currentOffset . $i * $limit )));
                }
                $batchResponses = $batchPromises;
                for ($i = 0; $i < count($batchResponses); $i++) {
                    $page = $this->safe_list($batchResponses[$i], 'data', $batchResponses[$i]) || array();
                    $markets = $this->array_concat($markets, $page);
                    if (strlen($page) < $limit) {
                        $done = true;
                        break;
                    }
                }
                $currentOffset .= $BATCH_SIZE * $limit;
                if ($done) {
                    break;
                }
            }
        }
        $filtered = array();
        for ($i = 0; $i < count($markets); $i++) {
            $market = $markets[$i];
            $id = $this->safe_string($market, 'id');
            $conditionId = $this->safe_string($market, 'conditionId') || $this->safe_string($market, 'condition_id');
            if ($id === null && $conditionId === null) {
                continue;
            }
            $outcomes = array();
            $outcomesStr = $this->safe_string($market, 'outcomes');
            if ($outcomesStr !== null) {
                $parsedOutcomes = null;
                try {
                    $parsedOutcomes = json_decode($outcomesStr, $as_associative_array = true);
                } catch (Exception $e) {
                    $parsedOutcomes = null;
                }
                if ($parsedOutcomes !== null && strlen($parsedOutcomes) !== null) {
                    for ($j = 0; $j < count($parsedOutcomes); $j++) {
                        $outcomes[] = $parsedOutcomes[$j];
                    }
                } else {
                    $outcomesArray = explode(',', $outcomesStr);
                    for ($j = 0; $j < count($outcomesArray); $j++) {
                        $v = trim($outcomesArray[$j]);
                        if ($v !== '') {
                            $outcomes[] = $v;
                        }
                    }
                }
            }
            $clobTokenIds = $this->parse_clob_token_ids($this->safe_value($market, 'clobTokenIds'));
            if (strlen($outcomes) > 0) {
                for ($j = 0; $j < count($outcomes); $j++) {
                    $outcome = $outcomes[$j];
                    $clobTokenId = null;
                    if ($j < strlen($clobTokenIds)) {
                        $clobTokenId = $clobTokenIds[$j];
                    }
                    // Create a copy of the $market with the $outcome and $clobTokenId
                    $marketWithOutcome = $this->extend(array(), $market, array( 'optionType' => $outcome, 'id' => $clobTokenId ));
                    $filtered[] = $marketWithOutcome;
                }
            } else {
                // If no $outcomes, push the $market as-is
                $filtered[] = $market;
            }
        }
        return $this->parse_markets($filtered);
    }

    public function parse_clob_token_ids(mixed $clobTokenIds): array {
        if ($clobTokenIds === null) {
            return array();
        }
        if ((gettype($clobTokenIds) === 'array' && array_keys($clobTokenIds) === array_keys(array_keys($clobTokenIds)))) {
            return $clobTokenIds;
        }
        try {
            return json_decode($clobTokenIds, $as_associative_array = true);
        } catch (Exception $e) {
            return array();
        }
    }

    public function parse_market(array $market): array {
        // Check if id is provided ($e->g., from clobTokenId in fetchMarkets)
        $providedId = $this->safe_string($market, 'id');
        // Schema uses 'conditionId' (camelCase)
        $conditionId = $this->safe_string($market, 'conditionId');
        $question = $this->safe_string($market, 'question');
        // Schema uses 'questionID' (camelCase)
        $questionId = $this->safe_string($market, 'questionID');
        // Schema uses 'slug' (camelCase)
        $slug = $this->safe_string($market, 'slug');
        $active = $this->safe_bool($market, 'active', false);
        $closed = $this->safe_bool($market, 'closed', false);
        $archived = $this->safe_bool($market, 'archived', false);
        $outcomes = array();
        $outcomePrices = array();
        $outcomesStr = $this->safe_string($market, 'outcomes');
        if ($outcomesStr !== null) {
            $parsedOutcomes = null;
            try {
                $parsedOutcomes = json_decode($outcomesStr, $as_associative_array = true);
            } catch (Exception $e) {
                $parsedOutcomes = null;
            }
            if ($parsedOutcomes !== null && strlen($parsedOutcomes) !== null) {
                for ($i = 0; $i < count($parsedOutcomes); $i++) {
                    $outcomes[] = $parsedOutcomes[$i];
                }
            } else {
                $outcomesArray = explode(',', $outcomesStr);
                for ($i = 0; $i < count($outcomesArray); $i++) {
                    $v = trim($outcomesArray[$i]);
                    if ($v !== '') {
                        $outcomes[] = $v;
                    }
                }
            }
        }
        $outcomePricesStr = $this->safe_string($market, 'outcomePrices');
        if ($outcomePricesStr !== null) {
            $parsedPrices = null;
            try {
                $parsedPrices = json_decode($outcomePricesStr, $as_associative_array = true);
            } catch (Exception $e) {
                $parsedPrices = null;
            }
            if ($parsedPrices !== null && strlen($parsedPrices) !== null) {
                for ($i = 0; $i < count($parsedPrices); $i++) {
                    $outcomePrices[] = $this->parse_number($parsedPrices[$i]);
                }
            } else {
                $pricesArray = explode(',', $outcomePricesStr);
                for ($i = 0; $i < count($pricesArray); $i++) {
                    $v = trim($pricesArray[$i]);
                    if ($v !== '') {
                        $outcomePrices[] = $this->parse_number($v);
                    }
                }
            }
        }
        // Use $slug $symbol if available
        $baseId = $slug || $conditionId;
        $quoteId = $this->safe_string($this->options, 'defaultCollateral', 'USDC'); // Polymarket uses USDC currency
        // Market type - Polymarket is a prediction $market platform
        $marketType => MarketType = 'option'; // Using 'option' match for prediction markets
        $ammType = $this->safe_string($market, 'ammType');
        // Schema uses 'enableOrderBook' (camelCase)
        $enableOrderBook = $this->safe_bool($market, 'enableOrderBook', false);
        // Market metadata
        $category = $this->safe_string($market, 'category');
        $description = $this->safe_string($market, 'description');
        $tags = $this->safe_value($market, 'tags', array());
        $clobTokenIds = $this->parse_clob_token_ids($this->safe_value($market, 'clobTokenIds'));
        $outcomesInfo = array();
        $length = count($outcomes);
        if (strlen($outcomePrices) > $length) {
            $length = count($outcomePrices);
        }
        if (strlen($clobTokenIds) > $length) {
            $length = count($clobTokenIds);
        }
        for ($i = 0; $i < $length; $i++) {
            $outcome = null;
            if ($i < strlen($outcomes)) {
                $outcome = $outcomes[$i];
            }
            $price = null;
            if ($i < strlen($outcomePrices)) {
                $price = $this->parse_number($outcomePrices[$i]);
            }
            $clobId = null;
            if ($i < strlen($clobTokenIds)) {
                $clobId = $clobTokenIds[$i];
            }
            $outcomeId = (string) $i;
            if ($clobId !== null) {
                $outcomeId = $clobId;
            }
            $outcomesInfo[] = array(
                'id' => $outcomeId,
                'name' => $outcome,
                'price' => $price,
                'clobId' => $clobId,
                'assetId' => $clobId,
            );
        }
        // Parse dates - Schema uses 'endDateIso' (preferred) or 'endDate' (fallback)
        $endDateIso = $this->safe_string($market, 'endDateIso') || $this->safe_string($market, 'endDate');
        if ($endDateIso === null) {
            // When $endDateIso is null use a very far future date
            $endDateIso = $this->safe_string($this->options, 'defaultEndDateIso');
        }
        // Schema uses 'createdAt' (camelCase)
        $createdAt = $this->safe_string($market, 'createdAt');
        $createdTimestamp = null;
        if ($createdAt !== null) {
            $createdTimestamp = $this->parse8601($createdAt);
        }
        // Volume and $liquidity
        $volume = $this->safe_string($market, 'volume');
        $volumeNum = $this->safe_number($market, 'volumeNum');
        $liquidity = $this->safe_string($market, 'liquidity');
        $liquidityNum = $this->safe_number($market, 'liquidityNum');
        $feesEnabled = $this->safe_bool($market, 'feesEnabled', false);
        $makerBaseFee = $this->safe_number($market, 'makerBaseFee');
        $takerBaseFee = $this->safe_number($market, 'takerBaseFee');
        $base = $baseId;
        $quote = $quoteId;
        $settle = $quote; // Use $quote
        // Parse $expiry for option $symbol formatting
        // Handle date-only strings (YYYY-MM-DD) by converting to ISO8601 datetime
        $expiry = null;
        $expiryDatetime = $endDateIso;
        if ($endDateIso !== null) {
            $dateString = $endDateIso;
            // Check if it's a date-only string (YYYY-MM-DD format)
            if (mb_strpos($dateString, ':') === false) {
                // Append time to make it a valid ISO8601 datetime
                $dateString = $dateString . 'T00:00:00Z';
            }
            $expiry = $this->parse8601($dateString);
        }
        // Use $outcome from $market dict if available (is_array(fetchMarkets) && array_key_exists(set, fetchMarkets)), otherwise use default
        $optionType = $this->safe_string($market, 'optionType') || $this->safe_string($this->options, 'defaultOptionType');
        // Format $symbol with $expiry date following CCXT option format
        // Format => base/quote:$settle-YYMMDD-$strike-type
        $ymd = $this->yymmdd($expiry);
        $strikePlaceholder = '0'; // Use 0 for $strike $price while not provided by the exchange
        $optionTypeValue = null;
        if ($optionType === 'call') {
            $optionTypeValue = 'C';
        } elseif ($optionType === 'put') {
            $optionTypeValue = 'P';
        } elseif ($optionType !== null) {
            $optionTypeValue = $this->parse_option_type($optionType);
        }
        $symbol = $base . '/' . $quote . ':' . $settle . '-' . $ymd . '-' . $strikePlaceholder . '-' . $optionTypeValue;
        $strike = null;
        $contractSize = $this->parse_number('1');
        // Calculate fees based on $feesEnabled flag
        $takerFee = $this->parse_number('0');
        $makerFee = $this->parse_number('0');
        if ($feesEnabled) {
            // Fees are enabled - use $makerBaseFee and $takerBaseFee from schema
            // These are typically in basis points ($e->g., 200 = 2% = 0.02)
            if ($takerBaseFee !== null) {
                $takerFee = $takerBaseFee / 10000; // Convert basis points to decimal
            }
            if ($makerBaseFee !== null) {
                $makerFee = $makerBaseFee / 10000; // Convert basis points to decimal
            }
        }
        $created = $this->milliseconds(); // TODO change it
        if ($createdTimestamp !== null) {
            $created = $createdTimestamp;
        }
        $volumeValue = $this->parse_number('0');
        if ($volumeNum !== null) {
            $volumeValue = $volumeNum;
        } elseif ($volume !== null) {
            $volumeValue = $this->parse_number($volume);
        }
        $liquidityValue = $this->parse_number('0');
        if ($liquidityNum !== null) {
            $liquidityValue = $liquidityNum;
        } elseif ($liquidity !== null) {
            $liquidityValue = $this->parse_number($liquidity);
        }
        $marketId = $providedId;
        if ($marketId === null) {
            $marketId = $conditionId;
        }
        return array(
            'id' => $marketId,
            'symbol' => $symbol,
            'base' => $base,
            'quote' => $quote,
            'settle' => $settle,
            'baseId' => $baseId,
            'quoteId' => $quoteId,
            'settleId' => $settle,
            'type' => $marketType,
            'spot' => false,
            'margin' => false,
            'swap' => false,
            'future' => false,
            'option' => true, // Prediction markets are treated
            'active' => $enableOrderBook && $active && !$closed && !$archived,
            'contract' => true,
            'linear' => true, // Only linear makes sense
            'inverse' => null,
            'contractSize' => $contractSize,
            'expiry' => $expiry,
            'expiryDatetime' => $expiryDatetime,
            'strike' => $strike,
            'optionType' => $optionType,
            'taker' => $takerFee,
            'maker' => $makerFee,
            'precision' => array(
                'amount' => 6, // https://github.com/Polymarket/clob-client/blob/main/src/config.ts
                'price' => 6, // https://github.com/Polymarket/clob-client/blob/main/src/config.ts
            ),
            'limits' => array(
                'leverage' => array(
                    'min' => null,
                    'max' => null,
                ),
                'amount' => array(
                    'min' => 5, // Minimum order size
                    'max' => null,
                ),
                'price' => array(
                    'min' => 1e-6, // Prediction markets are >0 and <1
                    'max' => 1, // Prediction markets are 0-1
                ),
                'cost' => array(
                    'min' => null,
                    'max' => null,
                ),
            ),
            'created' => $created,
            'info' => $this->deep_extend($market, array(
                'outcomes' => $outcomes,
                'outcomePrices' => $outcomePrices,
                'outcomesInfo' => $outcomesInfo,
                'question' => $question,
                'slug' => $slug,
                'category' => $category,
                'description' => $description,
                'tags' => $tags,
                'condition_id' => $conditionId,
                'question_id' => $questionId,
                'asset_id' => $questionId,
                'ammType' => $ammType,
                'enableOrderBook' => $enableOrderBook,
                'volume' => $volumeValue,
                'liquidity' => $liquidityValue,
                'endDateIso' => $endDateIso,
                'createdAt' => $createdAt,
                'createdTimestamp' => $createdTimestamp,
                'clobTokenIds' => $clobTokenIds,
                'quoteDecimals' => 6,  // https://github.com/Polymarket/clob-client/blob/main/src/config.ts
                'baseDecimals' => 6, // https://github.com/Polymarket/clob-client/blob/main/src/config.ts
            )),
        );
    }

    public function fetch_order_book(string $symbol, ?int $limit = null, $params = array ()): array {
        /**
         * fetches the order book for a $market
         *
         * @see https://docs.polymarket.com/api-reference/orderbook/get-order-book-summary
         *
         * @param {string} $symbol unified $symbol of the $market to fetch the order book for
         * @param {int} [$limit] the maximum amount of order book entries to return
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @param {string} [$params->token_id] the token ID for the specific outcome (required if $market has multiple outcomes)
         * @return {array} A dictionary of ~@link https://docs.ccxt.com/#/?id=order-book-structure order book structures~ indexed by $market symbols
         */
        $this->load_markets();
        $market = $this->market($symbol);
        $request = array();
        // Get token ID from $params or $market
        // Use $market['id'] which is the specific token ID for this outcome (YES/NO)
        // Do NOT use clobTokenIds[0] always picks the first outcome regardless of $symbol
        $tokenId = $this->safe_string($params, 'token_id');
        if ($tokenId === null) {
            $tokenId = $this->safe_string($market, 'id');
        }
        if ($tokenId === null) {
            throw new ArgumentsRequired($this->id . ' fetchOrderBook() requires a token_id parameter for $market ' . $symbol);
        }
        $request['token_id'] = $tokenId;
        $response = $this->clob_public_get_orderbook_token_id($this->extend($request, $params));
        return $this->parse_order_book($response, $symbol);
    }

    public function fetch_order_books(?array $symbols = null, ?int $limit = null, $params = array ()): OrderBooks {
        /**
         * fetches information on open orders with bid (buy) and ask (sell) prices, volumes and other data for multiple markets
         *
         * @see https://docs.polymarket.com/developers/CLOB/clients/methods-public#getorderbooks
         *
         * @param {string[]|null} $symbols list of unified $market $symbols, all $symbols fetched if null, default is null
         * @param {int} [$limit] the maximum amount of order book entries to return
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @return {array} a dictionary of ~@link https://docs.ccxt.com/#/?id=order-book-structure order book structures~ indexed by $market $symbol
         */
        $this->load_markets();
        if ($symbols === null) {
            $symbols = $this->symbols;
        }
        // Build list of token IDs to fetch order books for
        $tokenIds => stringarray() = array();
        $tokenIdToSymbol = array();
        for ($i = 0; $i < count($symbols); $i++) {
            $symbol = $symbols[$i];
            $market = $this->market($symbol);
            // Use $market['id'] which is the specific token ID for this outcome (YES/NO)
            // Do NOT use clobTokenIds[0] always picks the first outcome regardless of $symbol
            $tokenId = $this->safe_string($market, 'id');
            if ($tokenId !== null) {
                $tokenIds[] = $tokenId;
                $tokenIdToSymbol[$tokenId] = $symbol;
            }
        }
        if (strlen($tokenIds) === 0) {
            return array();
        }
        // Fetch order books for all token IDs at once using POST /books endpoint
        // See https://docs.polymarket.com/api-reference/orderbook/get-multiple-order-books-summaries-by-request
        // Request body => [array(token_id => "..."), array(token_id => "..."), ...]
        // Response format => array of order book objects, each with asset_id matching token_id
        $requestBody = array();
        for ($i = 0; $i < count($tokenIds); $i++) {
            $requestItem = array( 'token_id' => $tokenIds[$i] );
            if ($limit !== null) {
                $requestItem['limit'] = $limit;
            }
            $requestBody[] = $requestItem;
        }
        $response = $this->clob_public_post_books($this->extend(array( 'requests' => $requestBody ), $params));
        // Parse $response => array of order book objects, each with asset_id field
        // Response is directly an array => [array(asset_id => "...", bids => [...], asks => [...]), ...]
        $result = array();
        if ((gettype($response) === 'array' && array_keys($response) === array_keys(array_keys($response)))) {
            for ($i = 0; $i < count($response); $i++) {
                $orderbookData = $response[$i];
                $assetId = $this->safe_string($orderbookData, 'asset_id');
                $symbol = $tokenIdToSymbol[$assetId];
                if ($symbol !== null) {
                    try {
                        $orderbook = $this->parse_order_book($orderbookData, $symbol);
                        $result[$symbol] = $orderbook;
                    } catch (Exception $e) {
                        // Skip markets that fail to parse
                        continue;
                    }
                }
            }
        }
        return $result;
    }

    public function parse_order_book(array $orderbook, ?string $symbol = null, ?int $timestamp = null, ?string $bidsKey = 'bids', ?string $asksKey = 'asks', ?int $priceKey = 0, ?int $amountKey = 1, ?int $countOrIdKey = 2): array {
        // Polymarket CLOB $orderbook format (from /book endpoint)
        // See https://docs.polymarket.com/developers/CLOB/clients/methods-public#getorderbook
        // {
        //   "market" => "string",
        //   "asset_id" => "string",
        //   "timestamp" => "string",
        //   "bids" => array(
        //     {
        //       "price" => "0.65",  // string
        //       "size" => "100"     // string
        //     }
        //   ),
        //   "asks" => array(
        //     {
        //       "price" => "0.66",  // string
        //       "size" => "50"      // string
        //     }
        //   ),
        //   "min_order_size" => "string",
        //   "tick_size" => "string",
        //   "neg_risk" => boolean,
        //   "hash" => "string"
        // }
        // Note => Ensure $bids and $asks are always arrays to avoid Python transpilation issues
        // safeList can return null, which becomes None in Python, causing len() to fail
        $bids = $this->safe_list($orderbook, 'bids', array()) || array();
        $asks = $this->safe_list($orderbook, 'asks', array()) || array();
        // Note => Using 'const' without explicit type annotation to avoid Python transpilation issues
        // The transpiler incorrectly preserves TypeScript tuple type annotations (e.g., ' => [number, number][]') in Python code
        $parsedBids = array();
        $parsedAsks = array();
        for ($i = 0; $i < count($bids); $i++) {
            $bid = $bids[$i];
            $price = $this->safe_number($bid, 'priceNumber', $this->safe_number($bid, 'price'));
            $amount = $this->safe_number($bid, 'sizeNumber', $this->safe_number($bid, 'size'));
            if ($price !== null && $amount !== null) {
                $parsedBids[] = array( $price, $amount );
            }
        }
        for ($i = 0; $i < count($asks); $i++) {
            $ask = $asks[$i];
            $price = $this->safe_number($ask, 'priceNumber', $this->safe_number($ask, 'price'));
            $amount = $this->safe_number($ask, 'sizeNumber', $this->safe_number($ask, 'size'));
            if ($price !== null && $amount !== null) {
                $parsedAsks[] = array( $price, $amount );
            }
        }
        // Extract $timestamp from $orderbook response if available
        $orderbookTimestamp = $this->safe_string($orderbook, 'timestamp');
        $finalTimestamp = $timestamp;
        if ($orderbookTimestamp !== null) {
            // CLOB API returns $timestamp string, convert to milliseconds
            $finalTimestamp = $this->parse8601($orderbookTimestamp);
        }
        // Extract tick_size and neg_risk from $orderbook if available (useful $metadata)
        // These are also available via get_tick_size() and get_neg_risk() endpoints
        // Based on py-clob-client => get_tick_size() and get_neg_risk()
        $tickSize = $this->safe_string($orderbook, 'tick_size');
        $negRisk = $this->safe_bool($orderbook, 'neg_risk');
        $minOrderSize = $this->safe_string($orderbook, 'min_order_size');
        $result => OrderBook = array(
            'symbol' => $symbol,
            'bids' => $parsedBids,
            'asks' => $parsedAsks,
            'timestamp' => $finalTimestamp,
            'datetime' => $this->iso8601($finalTimestamp),
            'nonce' => null,
        );
        // Include tick_size, neg_risk, and min_order_size in info if available (useful $metadata)
        if ($tickSize !== null || $negRisk !== null || $minOrderSize !== null) {
            $metadata = array();
            if ($tickSize !== null) {
                $metadata['tick_size'] = $tickSize;
                // Update $market precision and info with tick_size if available
                if ($this->markets !== null && $symbol in $this->markets) {
                    $market = $this->markets[$symbol];
                    if ($market['precision']['price'] === null || $market['precision']['price'] === 6) {
                        $market['precision']['price'] = $this->parse_number($tickSize);
                    }
                    // Also keep $market['info']['tick_size'] in sync so buildAndSignOrder uses the
                    // correct rounding config (prevents $price like 0.003956 rounding to 0.00)
                    if ($this->safe_string($market['info'], 'tick_size') === null) {
                        $market['info']['tick_size'] = $tickSize;
                    }
                }
            }
            if ($negRisk !== null) {
                $metadata['neg_risk'] = $negRisk;
            }
            if ($minOrderSize !== null) {
                $metadata['min_order_size'] = $minOrderSize;
                // Update $market limits with min_order_size if available
                if ($this->markets !== null && $symbol in $this->markets) {
                    $market = $this->markets[$symbol];
                    if ($market['limits']['amount']['min'] === null) {
                        $market['limits']['amount']['min'] = $this->parse_number($minOrderSize);
                    }
                }
            }
            $result['info'] = $this->extend($orderbook, $metadata);
        }
        return $result;
    }

    public function fetch_ticker(string $symbol, $params = array ()): array {
        /**
         * fetches a price ticker, a statistical calculation with the information calculated over the past 24 hours for a specific $market
         *
         * @see https://docs.polymarket.com/api-reference/pricing/get-$market-price
         * @see https://docs.polymarket.com/api-reference/pricing/get-$midpoint-price
         *
         * @param {string} $symbol unified $symbol of the $market to fetch the ticker for
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @param {string} [$params->token_id] the token ID for the specific outcome (required if $market has multiple outcomes)
         * @param {string} [$params->side] the side => 'BUY' or 'SELL' (default => 'BUY')
         * @return {array} a ~@link https://docs.ccxt.com/#/?id=ticker-structure ticker structure~
         *
         * **Currently Populated Fields:**
         * - `bid` - Best bid price from POST /prices endpoint (BUY side)
         * - `ask` - Best ask price from POST /prices endpoint (SELL side)
         * - `last` - Midpoint price from GET /midpoint or lastTradePrice from $market info
         * - `open` - Calculated approximation => last / (1 . oneDayPriceChange)
         * - `change` - Calculated => last - open
         * - `percentage` - From oneDayPriceChange * 100 (from $market info)
         * - `volume` - From volumeNum or volume (from $market info)
         * - `timestamp` - From updatedAt (parsed from ISO string)
         * - `datetime` - ISO8601 formatted timestamp
         *
         * **Currently Undefined Fields (Available via Additional API Calls):**
         * - `high` - Can be fetched from GET /prices-history (24h price history) or GET /trades (24h trades)
         * - `low` - Can be fetched from GET /prices-history (24h price history) or GET /trades (24h trades)
         * - `bidVolume` - Can be calculated from GET /book (order book) by summing all bid sizes
         * - `askVolume` - Can be calculated from GET /book (order book) by summing all ask sizes
         * - `vwap` - Can be calculated from GET /trades (24h trades) using volume-weighted average
         * - `average` - Not available
         * - `indexPrice` - Not available
         * - `markPrice` - Not available
         *
         * **Enhancement Options:**
         *
         * 1. **For High/Low/More Accurate Open:**
         *    - Use fetchOHLCV() to get 24h price history => `await exchange.fetchOHLCV($symbol, '1h', since24hAgo, null, array(token_id => $tokenId))`
         *    - Calculate high/low from OHLCV data
         *    - Use first candle's open price for accurate 24h open
         *    - API => GET /prices-history (see https://docs.polymarket.com/developers/CLOB/timeseries)
         *
         * 2. **For VWAP:**
         *    - Use fetchTrades() to get 24h trades => `await exchange.fetchTrades($symbol, since24hAgo, null, array(token_id => $tokenId))`
         *    - Calculate => vwap = sum(trade.cost) / sum(trade.amount)
         *    - API => GET /trades (see https://docs.polymarket.com/api-reference/core/get-trades-for-a-user-or-markets)
         *
         * 3. **For Bid/Ask Volumes:**
         *    - Use fetchOrderBook() to get order book => `await exchange.fetchOrderBook($symbol, null, array(token_id => $tokenId))`
         *    - Calculate => bidVolume = sum of all bid[1] (sizes), askVolume = sum of all ask[1] (sizes)
         *    - API => GET /book (see https://docs.polymarket.com/api-reference/orderbook/get-order-book-summary)
         *
         * 4. **For More Accurate Last Price:**
         *    - Use GET /last-trade-price endpoint => `await exchange.clobPublicGetLastTradePrice(array(token_id => $tokenId))`
         *    - API => GET /last-trade-price (see https://docs.polymarket.com/api-reference/trades/get-last-trade-price)
         */
        $this->load_markets();
        $market = null;
        try {
            $market = $this->market($symbol);
        } catch (Exception $e) {
            $market = null;
        }
        if ($market === null) {
            $conditionId = $this->safe_string_2($params, 'condition_id', 'conditionId');
            $slug = $this->safe_string($params, 'slug');
            $tokenIdParam = $this->safe_string($params, 'token_id');
            $fallbackId = $conditionId || $slug || $tokenIdParam || $symbol;
            try {
                $market = $this->safe_market_with_fallback($fallbackId, null, $params);
            } catch (Exception $e) {
                $market = null;
            }
        }
        $marketInfo = ($market !== null) ? $this->safe_dict($market, 'info', array()) : array();
        // Get token ID from $params or $market
        // Use $market['id'] which is the specific token ID for this outcome (YES/NO)
        // Do NOT use clobTokenIds[0] always picks the first outcome regardless of $symbol
        $tokenId = $this->safe_string($params, 'token_id');
        if ($tokenId === null) {
            $tokenId = $this->safe_string($market, 'id');
        }
        if ($tokenId === null) {
            throw new ArgumentsRequired($this->id . ' fetchTicker() requires a token_id parameter for $market ' . $symbol);
        }
        // Fetch both BUY and SELL prices in a single POST /prices request
        // See https://docs.polymarket.com/api-reference/pricing/get-multiple-$market-prices-by-request
        $pricesResponse = $this->clob_public_post_prices($this->extend(array(
            'requests' => array(
                array( 'token_id' => $tokenId, 'side' => 'BUY' ),
                array( 'token_id' => $tokenId, 'side' => 'SELL' ),
            ),
        ), $params));
        $tokenPrices = $this->safe_dict($pricesResponse, $tokenId, array());
        $buyPrice = $this->safe_string($tokenPrices, 'BUY');
        $sellPrice = $this->safe_string($tokenPrices, 'SELL');
        // Fetch $midpoint if available (optional, ignore if not provided)
        $midpoint = null;
        try {
            $midpointResponse = $this->clob_public_get_midpoint($this->extend(array( 'token_id' => $tokenId ), $params));
            $midpoint = $this->safe_string($midpointResponse, 'mid');
        } catch (Exception $e) {
            // Ignore $midpoint if not available or fails
            $midpoint = null;
        }
        // Combine pricing data with $market info - already loaded from fetchMarkets
        $combinedData = $this->deep_extend($marketInfo, array(
            'buyPrice' => $buyPrice,
            'sellPrice' => $sellPrice,
            'midpoint' => $midpoint,
        ));
        return $this->parse_ticker($combinedData, $market);
    }

    public function fetch_tickers(?array $symbols = null, $params = array ()): array {
        /**
         * fetches price $tickers for multiple markets, statistical information calculated over the past 24 hours for each $market
         *
         * @see https://docs.polymarket.com/api-reference/pricing/get-multiple-$market-prices-by-request
         *
         * @param {string[]|null} $symbols unified $symbols of the markets to fetch the $ticker for, all $market $tickers are returned if not assigned
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @return {array} a dictionary of ~@link https://docs.ccxt.com/#/?id=$ticker-structure $ticker structures~
         */
        $this->load_markets();
        // Build list of token IDs to fetch prices for
        $tokenIds => stringarray() = array();
        $tokenIdToSymbol = array();
        $symbolsToFetch = $symbols || $this->symbols;
        for ($i = 0; $i < count($symbolsToFetch); $i++) {
            $symbol = $symbolsToFetch[$i];
            try {
                $market = $this->market($symbol);
                // Use $market['id'] which is the specific token ID for this outcome (YES/NO)
                // Do NOT use clobTokenIds[0] always picks the first outcome regardless of $symbol
                $tokenId = $this->safe_string($market, 'id');
                if ($tokenId !== null) {
                    $tokenIds[] = $tokenId;
                    $tokenIdToSymbol[$tokenId] = $symbol;
                }
            } catch (Exception $e) {
                continue;
            }
        }
        if (strlen($tokenIds) === 0) {
            return array();
        }
        // Fetch prices in batches using POST /prices with BUY+SELL requests per token.
        // Response format => array([token_id] => array(BUY => price, SELL => price))
        // See https://docs.polymarket.com/api-reference/pricing/get-multiple-$market-prices-by-request
        // Note => lastTradePrice, bestBid, bestAsk are already in $marketInfo from loadMarkets() (Gamma API)
        // and serve in parseTicker() when the pricing API has no orderbook data.
        $BATCH_TOKEN_SIZE = 250;
        $allPricesResponse = array();
        $batchStart = 0;
        while ($batchStart < strlen($tokenIds)) {
            $batchTokenIds = mb_substr($tokenIds, $batchStart, $batchStart . $BATCH_TOKEN_SIZE - $batchStart);
            $batchRequests = array();
            for ($j = 0; $j < count($batchTokenIds); $j++) {
                $batchRequests[] = array( 'token_id' => $batchTokenIds[$j], 'side' => 'BUY' );
                $batchRequests[] = array( 'token_id' => $batchTokenIds[$j], 'side' => 'SELL' );
            }
            $batchResponse = $this->clob_public_post_prices(array( 'requests' => $batchRequests ));
            $allPricesResponse = $this->deep_extend($allPricesResponse, $batchResponse);
            $batchStart = $batchStart . $BATCH_TOKEN_SIZE;
        }
        // Parse prices and build $tickers
        $tickers = array();
        for ($i = 0; $i < count($tokenIds); $i++) {
            $tokenId = $tokenIds[$i];
            $symbol = $tokenIdToSymbol[$tokenId];
            try {
                $market = $this->market($symbol);
                $tokenPrices = $this->safe_dict($allPricesResponse, $tokenId, array());
                $buyPrice = $this->safe_string($tokenPrices, 'BUY');
                $sellPrice = $this->safe_string($tokenPrices, 'SELL');
                $marketInfo = $this->safe_dict($market, 'info', array());
                $combinedData = $this->deep_extend($marketInfo, array(
                    'buyPrice' => $buyPrice,
                    'sellPrice' => $sellPrice,
                ));
                $ticker = $this->parse_ticker($combinedData, $market);
                $tickers[$symbol] = $ticker;
            } catch (Exception $e) {
                continue;
            }
        }
        return $tickers;
    }

    public function parse_ticker(array $ticker, ?array $market = null): array {
        /**
         * parses a $ticker data structure from Polymarket API response
         * @param {array} $ticker ticker data structure from Polymarket API
         * @param {array} [$market] $market structure
         * @return {array} a ~@link https://docs.ccxt.com/#/?id=$ticker-structure $ticker structure~
         *
         * **Data Sources:**
         * - Market info from fetchMarkets() ($volume, $oneDayPriceChange, $lastTradePrice, etc.)
         * - Pricing API ($buyPrice, $sellPrice, $midpoint)
         * - Market metadata (updatedAt, $volume24hr, $volume1wk, $volume1mo, $volume1yr)
         *
         * **Currently Parsed Fields:**
         * - `$bid` - From $buyPrice (POST /prices BUY side) or $bestBid ($market info)
         * - `$ask` - From $sellPrice (POST /prices SELL side) or $bestAsk ($market info)
         * - `$last` - From $midpoint (GET /midpoint) or $lastTradePrice ($market info)
         * - `$open` - Calculated => $last / (1 . $oneDayPriceChange) when both available
         * - `$change` - Calculated => $last - $open
         * - `$percentage` - From $oneDayPriceChange * 100
         * - `$volume` - From volumeNum or $volume ($market info)
         * - `$timestamp` - From updatedAt (ISO string $parsed to milliseconds)
         * - `$datetime` - ISO8601 formatted $timestamp
         *
         * **Fields Set to Undefined (Can Be Enhanced):**
         * - `$high` - Not available in current data sources. Can be calculated from:
         *   - Price history => max(...ohlcvData.map(c => c[2])) where c[2] is $high
         *   - Trades => max(...trades.map(t => t.price))
         * - `$low` - Not available in current data sources. Can be calculated from:
         *   - Price history => min(...ohlcvData.map(c => c[3])) where c[3] is $low
         *   - Trades => min(...trades.map(t => t.price))
         * - `$bidVolume` - Not available. Can be calculated from order book:
         *   - $orderbook->bids.reduce((sum, $bid) => sum . $bid[1], 0)
         * - `$askVolume` - Not available. Can be calculated from order book:
         *   - $orderbook->asks.reduce((sum, $ask) => sum . $ask[1], 0)
         * - `vwap` - Not available. Can be calculated from $trades:
         *   - $totalCost = $trades->reduce((sum, t) => sum . t.cost, 0)
         *   - $totalVolume = $trades->reduce((sum, t) => sum . t.amount, 0)
         *   - vwap = $totalCost / $totalVolume
         *
         * **To Enhance Ticker Data:**
         * Before calling parseTicker(), you can fetch additional data and add it to the $ticker dict:
         *
         * ```typescript
         * // Example => Add high/low from $price history
         * $since24h = exchange.milliseconds() - 24 * 60 * 60 * 1000;
         * $ohlcv = exchange.fetchOHLCV($symbol, '1h', $since24h, null, array(token_id => $tokenId));
         * if (strlen($ohlcv) > 0) {
         *     $highs = $ohlcv->map(c => c[2]); // OHLCV[2] is $high
         *     $lows = $ohlcv->map(c => c[3]);  // OHLCV[3] is $low
         *     $ticker['high'] = max(...highs);
         *     $ticker['low'] = min(...lows);
         *     $ticker['open'] = $ohlcv[0][1]; // First candle's $open
         * }
         *
         * // Example => Add VWAP from $trades
         * $trades = exchange.fetchTrades($symbol, $since24h, null, array(token_id => $tokenId));
         * if (strlen($trades) > 0) {
         *     $totalCost = 0;
         *     $totalVolume = 0;
         *     for ($i = 0; $i < count($trades); $i++) {
         *         $totalCost .= $trades[$i]['cost'];
         *         $totalVolume .= $trades[$i]['amount'];
         *     }
         *     $ticker['vwap'] = $totalVolume > 0 ? $totalCost / $totalVolume : null;
         * }
         *
         * // Example => Add bid/ask volumes from order book
         * $orderbook = exchange.fetchOrderBook($symbol, null, array(token_id => $tokenId));
         * $bidVolume = 0;
         * $askVolume = 0;
         * for ($i = 0; $i < count($orderbook['bids']); $i++) {
         *     $bidVolume .= $orderbook['bids'][$i][1];
         * }
         * for ($i = 0; $i < count($orderbook['asks']); $i++) {
         *     $askVolume .= $orderbook['asks'][$i][1];
         * }
         * $ticker['bidVolume'] = $bidVolume;
         * $ticker['askVolume'] = $askVolume;
         * ```
         */
        // Polymarket $ticker format from $market data
        $symbol = $market ? $market['symbol'] : null;
        if ($market === null) {
            $conditionId = $this->safe_string_2($ticker, 'condition_id', 'conditionId');
            $slug = $this->safe_string($ticker, 'slug');
            $tokenId = $this->safe_string($ticker, 'token_id');
            $fallbackId = $conditionId || $slug || $tokenId;
            if ($fallbackId !== null || $slug !== null) {
                try {
                    $market = $this->safe_market_with_fallback($fallbackId || $slug, null, $ticker);
                    $symbol = $this->safe_string($market, 'symbol', $symbol);
                } catch (Exception $e) {
                    $market = null;
                }
            }
        }
        // Parse outcome prices
        $outcomePricesStr = $this->safe_string($ticker, 'outcomePrices');
        $outcomePrices = array();
        if ($outcomePricesStr) {
            try {
                $parsed = json_decode($outcomePricesStr, $as_associative_array = true);
                // Note => Ensure all elements are numbers - JSON.parse may return strings
                // Convert each element to a number to avoid Python multiplication errors
                if ($parsed !== null && $parsed !== null && strlen($parsed) !== null) {
                    for ($i = 0; $i < count($parsed); $i++) {
                        $price = $this->parse_number($parsed[$i]);
                        if ($price !== null) {
                            $outcomePrices[] = $price;
                        }
                    }
                }
            } catch (Exception $e) {
                // Note => Using for loop instead of .map() to avoid Python transpilation issues
                // Arrow functions with type annotations ($e->g., '(p => string) =>') are incorrectly preserved in Python
                $pricesArray = explode(',', $outcomePricesStr);
                for ($i = 0; $i < count($pricesArray); $i++) {
                    $price = $this->parse_number(trim($pricesArray[$i]));
                    if ($price !== null) {
                        $outcomePrices[] = $price;
                    }
                }
            }
        }
        $last = null;
        $bid = null;
        $ask = null;
        $high = null;
        $low = null;
        // Volume data
        $volume = $this->safe_number($ticker, 'volumeNum', $this->safe_number($ticker, 'volume'));
        $volume24hr = $this->safe_number($ticker, 'volume24hr');
        $volume1wk = $this->safe_number($ticker, 'volume1wk');
        $volume1mo = $this->safe_number($ticker, 'volume1mo');
        $volume1yr = $this->safe_number($ticker, 'volume1yr');
        // Price changes
        $oneDayPriceChange = $this->safe_number($ticker, 'oneDayPriceChange');
        // Best bid/ask from pricing API (BUY = $bid, SELL = $ask)
        $buyPrice = $this->safe_number($ticker, 'buyPrice');
        $sellPrice = $this->safe_number($ticker, 'sellPrice');
        $midpoint = $this->safe_number($ticker, 'midpoint');
        // Use pricing API data if available
        if ($buyPrice !== null) {
            $bid = $buyPrice;
        }
        if ($sellPrice !== null) {
            $ask = $sellPrice;
        }
        if ($midpoint !== null) {
            $last = $midpoint;
        }
        // Fallback to $ticker data if pricing API data not available
        $bestBid = $this->safe_number($ticker, 'bestBid');
        $bestAsk = $this->safe_number($ticker, 'bestAsk');
        $lastTradePrice = $this->safe_number($ticker, 'lastTradePrice');
        if ($bid === null && $bestBid !== null) {
            $bid = $bestBid;
        }
        if ($ask === null && $bestAsk !== null) {
            $ask = $bestAsk;
        }
        if ($last === null && $lastTradePrice !== null) {
            $last = $lastTradePrice;
        }
        if ($last === null && $bid !== null && $ask !== null) {
            $last = ($bid . $ask) / 2;
        }
        // Fallback to $market outcomesInfo from loadMarkets() (Gamma API)
        // Match by $market->id (clobTokenId) to find the correct outcome $price
        if ($last === null && $market !== null) {
            $marketInfoForPrices = $this->safe_dict($market, 'info', array());
            $outcomesInfoList = $this->safe_list($marketInfoForPrices, 'outcomesInfo', array());
            $marketId = $this->safe_string($market, 'id');
            for ($k = 0; $k < count($outcomesInfoList); $k++) {
                $outcomeInfo = $this->safe_dict($outcomesInfoList, $k, array());
                $outcomeId = $this->safe_string($outcomeInfo, 'id');
                if ($outcomeId === $marketId) {
                    $last = $this->safe_number($outcomeInfo, 'price');
                    break;
                }
            }
        }
        // Timestamp
        $updatedAtString = $this->safe_string($ticker, 'updatedAt');
        $timestamp = $updatedAtString ? $this->parse8601($updatedAtString) : null;
        $datetime = $timestamp ? $this->iso8601($timestamp) : null;
        // Open (previous closing $price - approximated)
        $open = null;
        if ($last !== null && $oneDayPriceChange !== null) {
            $open = $last / (1 . $oneDayPriceChange);
        }
        // Change and $percentage
        $change = null;
        if ($last !== null && $open !== null) {
            $change = $last - $open;
        }
        $percentage = null;
        if ($oneDayPriceChange !== null) {
            $percentage = $oneDayPriceChange * 100;
        }
        // Add additional Polymarket-specific fields to info
        $tickerInfo = $this->safe_dict($ticker, 'info', array());
        $extendedInfo = $this->deep_extend($tickerInfo, array(
            'buyPrice' => $buyPrice,
            'sellPrice' => $sellPrice,
            'midpoint' => $midpoint,
            'lastTradePrice' => $lastTradePrice,
            'volume24hr' => $volume24hr,
            'volume1wk' => $volume1wk,
            'volume1mo' => $volume1mo,
            'volume1yr' => $volume1yr,
        ));
        return array(
            'symbol' => $symbol,
            'info' => $this->deep_extend($ticker, array( 'info' => $extendedInfo )),
            'timestamp' => $timestamp,
            'datetime' => $datetime,
            'high' => $high,
            'low' => $low,
            'bid' => $bid,
            'bidVolume' => null,
            'ask' => $ask,
            'askVolume' => null,
            'vwap' => null,
            'open' => $open,
            'close' => $last,
            'last' => $last,
            'previousClose' => $open,
            'change' => $change,
            'percentage' => $percentage,
            'average' => null,
            'baseVolume' => $volume,
            'quoteVolume' => $volume,
            'indexPrice' => null,
            'markPrice' => null,
        );
    }

    public function fetch_trades(string $symbol, ?int $since = null, ?int $limit = null, $params = array ()): array {
        /**
         * get the list of most recent trades for a particular $symbol
         *
         * @see https://docs.polymarket.com/api-reference/core/get-trades-for-a-user-or-markets
         *
         * @param {string} $symbol unified $symbol of the $market to fetch trades for
         * @param {int} [$since] timestamp in ms of the earliest trade to fetch
         * @param {int} [$limit] the maximum amount of trades to fetch (default => 100, max => 10000)
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @param {int} [$params->offset] $offset for pagination (default => 0, max => 10000)
         * @param {boolean} [$params->takerOnly] if true, returns only trades where the user is the taker (default => true)
         * @param {string} [$params->side] filter by $side => 'BUY' or 'SELL'
         * @return {Trade[]} a list of ~@link https://docs.ccxt.com/#/?id=public-trades trade structures~
         */
        $this->load_markets();
        $market = $this->market($symbol);
        $marketInfo = $this->safe_dict($market, 'info', array());
        // Get condition_id from $market info (this is the $market ID for Polymarket)
        $conditionId = $this->safe_string($marketInfo, 'condition_id', $market['id']);
        $request = array(
            'market' => array( $conditionId ), // Data API expects an array of condition IDs
        );
        // Note => Data API /trades endpoint supports $limit (default => 100, max => 10000) and $offset for pagination
        // The 'since' parameter is not directly supported by the REST API
        if ($limit !== null) {
            $request['limit'] = min ($limit, 10000); // Cap at max 10000
        }
        $offset = $this->safe_integer($params, 'offset');
        if ($offset !== null) {
            $request['offset'] = $offset;
        }
        $takerOnly = $this->safe_bool($params, 'takerOnly', true);
        $request['takerOnly'] = $takerOnly;
        $side = $this->safe_string_upper($params, 'side');
        if ($side !== null) {
            $request['side'] = $side;
        }
        $response = $this->data_public_get_trades($this->extend($request, $this->omit($params, array( 'offset', 'takerOnly', 'side' ))));
        $tradesData = array();
        if ((gettype($response) === 'array' && array_keys($response) === array_keys(array_keys($response)))) {
            $tradesData = $response;
        } else {
            $dataList = $this->safe_list($response, 'data', array());
            if ($dataList !== null) {
                $tradesData = $dataList;
            }
        }
        return $this->parse_trades($tradesData, $market, $since, $limit);
    }

    public function parse_trade(array $trade, ?array $market = null): array {
        // Detect Data API format (has $conditionId field) vs CLOB format (has market/asset_id fields)
        // Check for both camelCase and snake_case for robustness
        $conditionId = $this->safe_string_2($trade, 'conditionId', 'condition_id');
        $isDataApiFormat = $conditionId !== null;
        if ($isDataApiFormat) {
            // Data API format => https://docs.polymarket.com/api-reference/core/get-trades-for-a-user-or-markets
            // {
            //   "proxyWallet" => "0x...",
            //   "side" => "BUY",
            //   "asset" => "<string>",
            //   "conditionId" => "0x...",
            //   "size" => 123,
            //   "price" => 123,
            //   "timestamp" => 123,
            //   "transactionHash" => "0x...",
            //   ...
            // }
            // Use transactionHash, check both camelCase and snake_case
            $id = $this->safe_string_2($trade, 'transactionHash', 'transaction_hash');
            $symbol = null;
            if ($market !== null && $market['symbol'] !== null) {
                $symbol = $market['symbol'];
            } elseif ($conditionId !== null) {
                $resolved = $this->safe_market_with_fallback($conditionId, null, $trade);
                $resolvedSymbol = $this->safe_string($resolved, 'symbol');
                if ($resolvedSymbol !== null) {
                    $symbol = $resolvedSymbol;
                } else {
                    $symbol = $conditionId;
                }
            }
            $timestampSeconds = $this->safe_integer($trade, 'timestamp');
            $timestamp = null;
            if ($timestampSeconds !== null) {
                $timestamp = $timestampSeconds * 1000;
            }
            $side = $this->safe_string_lower($trade, 'side');
            $price = $this->safe_number($trade, 'price');
            $amount = $this->safe_number($trade, 'size');
            $cost = null;
            if ($price !== null && $amount !== null) {
                $cost = $price * $amount;
            }
            // Data API doesn't provide $fee information
            return array(
                'id' => $id,
                'info' => $trade,
                'timestamp' => $timestamp,
                'datetime' => $this->iso8601($timestamp),
                'symbol' => $symbol,
                'type' => null,
                'side' => $side,
                'takerOrMaker' => null, // Data API doesn't provide this information
                'price' => $price,
                'amount' => $amount,
                'cost' => $cost,
                'fee' => null, // Data API doesn't provide $fee information
                'order' => null, // Data API doesn't provide order ID
            );
        } else {
            // CLOB Trade format (backward compatibility)
            // interface Trade {
            //   $id => string;
            //   taker_order_id => string;
            //   $market => string;
            //   asset_id => string;
            //   $side => Side;
            //   size => string;
            //   fee_rate_bps => string;
            //   $price => string;
            //   status => string;
            //   match_time => string;
            //   last_update => string;
            //   outcome => string;
            //   bucket_index => number;
            //   owner => string;
            //   maker_address => string;
            //   maker_orders => MakerOrderarray();
            //   transaction_hash => string;
            //   trader_side => "TAKER" | "MAKER";
            // }
            $id = $this->safe_string($trade, 'id');
            $assetId = $this->safe_string($trade, 'asset_id');
            $tradeMarket = $this->safe_string($trade, 'market');
            $symbol = null;
            if ($market !== null && $market['symbol'] !== null) {
                $symbol = $market['symbol'];
            } elseif ($tradeMarket !== null) {
                $resolved = $this->safe_market_with_fallback($tradeMarket, null, $trade);
                $resolvedSymbol = $this->safe_string($resolved, 'symbol');
                if ($resolvedSymbol !== null) {
                    $symbol = $resolvedSymbol;
                } else {
                    $symbol = $tradeMarket;
                }
            } elseif ($assetId !== null) {
                $resolved = $this->safe_market_with_fallback($assetId, $market, $trade);
                $resolvedSymbol = $this->safe_string($resolved, 'symbol');
                if ($resolvedSymbol !== null) {
                    $symbol = $resolvedSymbol;
                } else {
                    $symbol = $assetId;
                }
            }
            $matchTime = $this->safe_integer($trade, 'match_time');
            $timestamp = null;
            if ($matchTime !== null) {
                $timestamp = $matchTime * 1000;
            }
            // Top-level fields are from the taker perspective; for maker trades use maker_orders
            $side = $this->safe_string_lower($trade, 'side');
            $price = $this->safe_number($trade, 'price');
            $amount = $this->safe_number($trade, 'size');
            $feeRateBps = $this->safe_number($trade, 'fee_rate_bps');
            $traderSide = $this->safe_string_upper($trade, 'trader_side');
            if ($traderSide === 'MAKER') {
                $makerOrders = $this->safe_value($trade, 'maker_orders', array());
                $proxyWallet = $this->get_proxy_wallet_address();
                $userAddress = strtolower($proxyWallet);
                $matched = false;
                for ($i = 0; $i < count($makerOrders); $i++) {
                    $m = $makerOrders[$i];
                    $mAddr = $this->safe_string($m, 'maker_address');
                    if ($mAddr !== null) {
                        $mAddrLower = strtolower($mAddr);
                        if ($mAddrLower === $userAddress) {
                                $price = $this->safe_number($m, 'price');
                                $amount = $this->safe_number($m, 'matched_amount');
                                $side = $this->safe_string_lower($m, 'side');
                                $feeRateBps = $this->safe_number($m, 'fee_rate_bps');
                                $matched = true;
                                break;
                        }
                    }
                }
                if (!$matched) {
                    $m = $makerOrders[0];
                    $price = $this->safe_number($m, 'price');
                    $amount = $this->safe_number($m, 'matched_amount');
                    $side = $this->safe_string_lower($m, 'side');
                    $feeRateBps = $this->safe_number($m, 'fee_rate_bps');
                }
            }
            $feeCost = null;
            if ($feeRateBps !== null && $price !== null && $amount !== null) {
                $feeCost = $price * $amount * $feeRateBps / 10000;
            }
            $fee = null;
            if ($feeCost !== null) {
                $fee = array(
                    'cost' => $feeCost,
                    'currency' => $this->safe_string($this->options, 'defaultCollateral', 'USDC'),
                    'rate' => $feeRateBps !== null ? $feeRateBps / 10000 : null,
                );
            }
            $cost = ($price !== null && $amount !== null) ? $price * $amount : null;
            return array(
                'id' => $id,
                'info' => $trade,
                'timestamp' => $timestamp,
                'datetime' => $this->iso8601($timestamp),
                'symbol' => $symbol,
                'type' => null,
                'side' => $side,
                'takerOrMaker' => $this->safe_string_lower($trade, 'trader_side'),
                'price' => $price,
                'amount' => $amount,
                'cost' => $cost,
                'fee' => $fee,
                'order' => $this->safe_string($trade, 'taker_order_id'),
            );
        }
    }

    public function fetch_ohlcv(string $symbol, string $timeframe = '1h', ?int $since = null, ?int $limit = null, $params = array ()): array {
        /**
         * fetches historical candlestick data containing the open, high, low, and close price, and the volume of a $market
         *
         * @see https://docs.polymarket.com/developers/CLOB/clients/methods-public#getpriceshistory
         *
         * @param {string} $symbol unified $symbol of the $market to fetch OHLCV data for
         * @param {string} $timeframe the length of time each candle represents
         * @param {int} [$since] timestamp in ms of the earliest candle to fetch
         * @param {int} [$limit] the maximum amount of candles to fetch
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @param {string} [$params->token_id] the token ID for the specific outcome (required if $market has multiple outcomes)
         * @param {int} [$params->endTs] timestamp in seconds for the ending date filter
         * @param {number} [$params->fidelity] data fidelity/quality
         * @return {int[][]} A list of candles ordered, open, high, low, close, volume
         */
        $this->load_markets();
        $market = $this->market($symbol);
        $request = array();
        // Get token ID from $params or $market
        // Use $market['id'] which is the specific token ID for this outcome (YES/NO)
        // Do NOT use clobTokenIds[0] always picks the first outcome regardless of $symbol
        $tokenId = $this->safe_string($params, 'token_id');
        if ($tokenId === null) {
            $tokenId = $this->safe_string($market, 'id');
        }
        if ($tokenId === null) {
            throw new ArgumentsRequired($this->id . ' fetchOHLCV() requires a token_id parameter for $market ' . $symbol);
        }
        $request['market'] = $tokenId; // API uses 'market' parameter for token_id
        // Note => REST API /prices-history endpoint requires either:
        // 1. startTs and $endTs (mutually exclusive with interval)
        // 2. interval (mutually exclusive with startTs/endTs)
        // See https://docs.polymarket.com/developers/CLOB/timeseries
        // Supported intervals => "1m", "1h", "6h", "1d", "1w", "max"
        // CCXT will automatically reject unsupported timeframes based on the 'timeframes' definition
        $endTs = $this->safe_integer($params, 'endTs');
        if ($since !== null || $endTs !== null) {
            // Use startTs/endTs when time range is specified
            if ($since !== null) {
                // Convert milliseconds to seconds for API
                $request['startTs'] = $this->parse_to_int($since / 1000);
            }
            if ($endTs !== null) {
                $request['endTs'] = $endTs;
            }
        } else {
            // Use interval when no time range is specified
            // CCXT will validate the $timeframe against the 'timeframes' definition
            // Map to API format ($timeframe should already be validated by CCXT)
            $request['interval'] = $timeframe;
        }
        // Fidelity parameter controls data granularity (e.g., 720 for 12-hour intervals)
        // If not provided, API may use default $fidelity
        $fidelity = $this->safe_number($params, 'fidelity');
        // Polymarket enforces minimum $fidelity per interval (e.g. interval=1m requires $fidelity>=10)
        // Avoid leaking a server-side validation error back to the user when a too-low value is supplied.
        if ($timeframe === '1m') {
            if ($fidelity === null) {
                $fidelity = 10;
            } else {
                $fidelity = min (10, $fidelity);
            }
        }
        if ($fidelity !== null) {
            $request['fidelity'] = $fidelity;
        }
        $remainingParams = $this->omit($params, array( 'token_id', 'endTs', 'fidelity' ));
        $response = $this->clob_public_get_prices_history($this->extend($request, $remainingParams));
        $ohlcvData = array();
        if ((gettype($response) === 'array' && array_keys($response) === array_keys(array_keys($response)))) {
            $ohlcvData = $response;
        } else {
            // Response has 'history' key containing the array
            $ohlcvData = $this->safe_list($response, 'history', array()) || array();
        }
        return $this->parse_ohlcvs($ohlcvData, $market, $timeframe, $since, $limit);
    }

    public function parse_ohlcv(mixed $ohlcv, ?array $market = null): array {
        // Polymarket MarketPrice format from getPricesHistory
        // See https://docs.polymarket.com/developers/CLOB/clients/methods-public#getpriceshistory
        // {
        //   "t" => number,  // $timestamp in seconds
        //   "p" => number   // $price
        // }
        // Note => Polymarket only returns $price data, not full OHLCV
        // We'll use the $price, high, low, and close, with volume
        $timestamp = $this->safe_integer($ohlcv, 't');
        $price = $this->safe_number($ohlcv, 'p');
        // Convert $timestamp from seconds to milliseconds
        if ($timestamp !== null) {
            $timestamp = $timestamp * 1000;
        }
        return array(
            $timestamp,
            $price, // open
            $price, // high (same since we only have $price)
            $price, // low (same since we only have $price)
            $price, // close
            0,     // volume (not available in $price history)
        );
    }

    public function get_rounding_config(string $tickSize): array {
        /**
         * Get rounding configuration based on tick size (matches ROUNDING_CONFIG from official SDK)
         * @param {string} $tickSize tick size string (e.g., '0.1', '0.01', '0.001', '0.0001')
         * @return {array} rounding configuration with price, size, and amount decimal places
         */
        // Determine rounding config based on tick size (matches ROUNDING_CONFIG from SDK)
        // Returns => array( price => number, size => number, amount => number )
        $priceDecimals = 2;
        $sizeDecimals = 2;
        $amountDecimals = 4;
        if ($tickSize === '0.1') {
            $priceDecimals = 1;
            $sizeDecimals = 2;
            $amountDecimals = 3;
        } elseif ($tickSize === '0.01') {
            $priceDecimals = 2;
            $sizeDecimals = 2;
            $amountDecimals = 4;
        } elseif ($tickSize === '0.001') {
            $priceDecimals = 3;
            $sizeDecimals = 2;
            $amountDecimals = 5;
        } elseif ($tickSize === '0.0001') {
            $priceDecimals = 4;
            $sizeDecimals = 2;
            $amountDecimals = 6;
        }
        return array(
            'price' => $priceDecimals,
            'size' => $sizeDecimals,
            'amount' => $amountDecimals,
        );
    }

    public function round_down(string $value, float $decimals): string {
        /**
         * Round down (truncate) a $value to specific decimal places
         * @param {string} $value value to round down
         * @param {number} $decimals number of decimal places
         * @return {string} rounded down $value
         */
        return $this->decimal_to_precision($value, 0, $decimals, 2, 5);
    }

    public function round_normal(string $value, float $decimals): string {
        /**
         * Round a $value normally to specific decimal places
         * @param {string} $value value to round
         * @param {number} $decimals number of decimal places
         * @return {string} rounded $value
         */
        return $this->decimal_to_precision($value, 1, $decimals, 2, 5);
    }

    public function round_up(string $value, float $decimals): string {
        /**
         * Round up a $value to specific decimal places
         * @param {string} $value value to round up
         * @param {number} $decimals number of decimal places
         * @return {string} rounded up $value
         */
        return $this->decimal_to_precision($value, 2, $decimals, 2, 5);
    }

    public function decimal_places(string $value): float {
        /**
         * Count the number of decimal places in a string $value
         * @param {string} $value value to count decimal places for
         * @return {number} number of decimal places
         */
        $parts = explode('.', $value);
        if (strlen($parts) === 2) {
            return count($parts[1]);
        }
        return 0;
    }

    public function to_token_decimals(string $value, float $decimals): string {
        /**
         * Convert a $value to token $decimals (smallest unit) by multiplying by 10^$decimals and truncating
         * @param {string} $value value to convert
         * @param {number} $decimals number of $decimals (e.g., 6 for USDC, 18 for tokens)
         * @return {string} $value in smallest unit
         */
        // Multiply by 10^$decimals and truncate to integer
        $multiplier = $this->integer_precision_to_amount($this->number_to_string(-$decimals));
        return Precise::string_div(Precise::string_mul($value, $multiplier), '1', 0);
    }

    public function build_and_sign_order(string $tokenId, string $side, string $size, ?string $price = null, ?array $market = null, $params = array ()): array {
        /**
         * Builds and signs an $order with EIP-712 according to Polymarket $order-utils specification
         *
         * @see https://github.com/Polymarket/clob-$order-utils
         * @see https://github.com/Polymarket/clob-client/blob/main/src/order-builder/builder.ts
         * @see https://github.com/Polymarket/python-$order-utils/blob/main/py_order_utils/builders/order_builder.py
         *
         * @param {string} $tokenId the token ID
         * @param {string} $side 'BUY' or 'SELL'
         * @param {string} $size $order $size
         * @param {string} [$price] $order $price (required for limit orders)
         * @param {array} [$market] $market structure (optional, used to get fees)
         * @param {array} [$params] extra parameters
         * @param {number} [$params->expiration] $expiration timestamp in seconds (default => 30 days from now)
         * @param {number} [$params->nonce] $order $nonce (default => 0)
         * @param {number} [$params->feeRateBps] fee rate in basis points (default => from $market or 200 bps)
         * @param {string} [$params->maker] $maker address (default => getMainWalletAddress())
         * @param {string} [$params->taker] $taker address (default => zero address)
         * @param {string} [$params->signer] $signer address (default => $maker address)
         * @param {number} [$params->signatureType] $signature type (default => from options.signatureType or options.signatureTypes.EOA).
         * @param {string} [$params->orderType] $order type => 'GTC', 'IOC', 'FOK', 'GTD' (default => 'GTC' for limit orders, 'FOK' for $market orders)
         * @param {boolean} [$params->negRisk] true if the $market is a neg risk (multi-outcome) $market; overrides $market->info.neg_risk
         * @return {array} signed $order object ready for submission
         */
        // Get zero address constant (matches py-clob-client ZERO_ADDRESS)
        // See https://github.com/Polymarket/py-clob-client/blob/main/py_clob_client/constants.py
        $zeroAddress = $this->safe_string($this->options, 'zeroAddress', '0x0000000000000000000000000000000000000000');
        // Get $signature type
        $signatureType = $this->get_signature_type($params);
        // Get $maker address (wallet address) - checksummed for signing
        $maker = $this->safe_string($params, 'maker');
        if ($maker === null) {
            $signatureTypes = $this->safe_dict($this->options, 'signatureTypes', array());
            $eoaSignatureType = $this->safe_integer($signatureTypes, 'EOA');
            if ($signatureType === $eoaSignatureType) {
                $maker = $this->get_main_wallet_address();
            } else {
                $maker = $this->get_proxy_wallet_address();
            }
        }
        $normalizedMaker = $this->normalize_address($maker);
        // Get $taker address (default => zero address for open orders)
        $taker = $this->safe_string($params, 'taker', $zeroAddress);
        $normalizedTaker = $this->normalize_address($taker);
        // Get fee rate in basis points from $market or $params
        $feeRateBps = $this->safe_integer($params, 'feeRateBps');
        if ($feeRateBps === null) {
            if ($market !== null) {
                // Try to get fee from $market structure
                $marketInfo = $this->safe_dict($market, 'info', array());
                // First try takerBaseFee from $market info (in basis points)
                $feeRateBps = $this->safe_integer($marketInfo, 'takerBaseFee');
                if ($feeRateBps === null) {
                    // Try $taker fee from parsed $market (decimal, convert to basis points)
                    $takerFee = $this->safe_number($market, 'taker');
                    if ($takerFee !== null) {
                        $feeRateBps = (int) round($takerFee * 10000);
                    }
                }
            }
            // Fallback to default fee rate from options if not found in $market
            if ($feeRateBps === null) {
                $feeRateBps = $this->safe_integer($this->options, 'defaultFeeRateBps', 200);
            }
        }
        // Get $expiration => GTC/IOC/FOK orders must have $expiration = 0 (no $expiration).
        // Only GTD orders use a future timestamp. buildOrder enforces this for normal flows,
        // but buildAndSignOrder may also be called directly, so we apply the same rule here.
        $expiration = $this->safe_integer($params, 'expiration');
        if ($expiration === null) {
            $timeInForce = $this->safe_string($params, 'timeInForce', 'GTC');
            $timeInForceUpper = strtoupper($timeInForce);
            if ($timeInForceUpper === 'GTD') {
                $nowSeconds = (int) floor($this->milliseconds() / 1000);
                $defaultExpirationDays = $this->safe_integer($this->options, 'defaultExpirationDays', 30);
                $expiration = $nowSeconds . ($defaultExpirationDays * 24 * 60 * 60);
            } else {
                $expiration = 0;
            }
        }
        // Get $nonce (default => 0 for regular orders)
        // The $nonce is used for on-chain batch cancellation => all orders sharing a non-zero $nonce
        // can be cancelled together. 0 means "no group" and is required for standard orders.
        // See https://github.com/Polymarket/clob-$order-utils/blob/main/src/order-builder/builder.ts
        $nonce = $this->safe_integer($params, 'nonce');
        if ($nonce === null) {
            $nonce = 0;
        }
        // Get $signer address (default => $maker address)
        $signer = $this->safe_string($params, 'signer');
        if ($signer === null) {
            $signer = $this->get_main_wallet_address();
        }
        $normalizedSigner = $this->normalize_address($signer);
        // Generate $salt (unique integer based on milliseconds for better uniqueness)
        $salt = $this->milliseconds();
        // Calculate $makerAmount and $takerAmount from $size and $price
        // Key steps => 1) Round down $size first, 2) Calculate other amount, 3) Round if needed, 4) Convert to smallest units
        // Get precision from $market info or use defaults (USDC => 6 decimals, Tokens => 18 decimals)
        $orderMarketInfo = array();
        if ($market !== null) {
            $orderMarketInfo = $this->safe_dict($market, 'info', array());
        }
        $marketPrecision = array();
        if ($market !== null) {
            $marketPrecision = $this->safe_dict($market, 'precision', array());
        }
        $quoteDecimals = $this->safe_integer($orderMarketInfo, 'quoteDecimals', $this->safe_integer($marketPrecision, 'price'));
        $baseDecimals = $this->safe_integer($orderMarketInfo, 'baseDecimals', $this->safe_integer($marketPrecision, 'amount'));
        $defaultTickSize = $this->safe_string($this->options, 'defaultTickSize');
        $tickSize = $this->safe_string($orderMarketInfo, 'tick_size', $defaultTickSize);
        $roundingConfig = $this->get_rounding_config($tickSize);
        $priceDecimals = $this->safe_integer($roundingConfig, 'price', 2);
        $sizeDecimals = $this->safe_integer($roundingConfig, 'size', 2);
        $amountDecimals = $this->safe_integer($roundingConfig, 'amount', 4);
        $isBuy = (strtoupper($side) === 'BUY');
        // Get $price => from parameter, or from $params->marketPrice for $market orders
        $orderPrice = $price;
        if ($orderPrice === null) {
            $orderPrice = $this->safe_string($params, 'marketPrice');
        }
        if ($orderPrice === null) {
            throw new ArgumentsRequired($this->id . ' buildAndSignOrder() requires a $price parameter or $params->marketPrice');
        }
        // Round $price and $size first, then calculate amounts (same logic for limit and $market orders)
        $rawPrice = $this->round_normal($orderPrice, $priceDecimals);
        // If the rounded $price is zero ($price is below tick resolution), auto-detect the needed
        // decimal precision from the actual $price value to avoid submitting a zero $makerAmount->
        if ($this->parse_number($rawPrice) === 0) {
            $orderPriceStr = $this->number_to_string($orderPrice);
            $dotIndex = mb_strpos($orderPriceStr, '.');
            $neededDecimals = $priceDecimals;
            if ($dotIndex >= 0) {
                $nonZeroPos = $dotIndex + 1;
                while ($nonZeroPos < strlen($orderPriceStr) && $orderPriceStr[$nonZeroPos] === '0') {
                    $nonZeroPos += 1;
                }
                $neededDecimals = $nonZeroPos - $dotIndex;
            }
            if ($neededDecimals > $priceDecimals) {
                $rawPrice = $this->round_normal($orderPrice, $neededDecimals);
            }
        }
        // Check if this is a $market $order for special decimal handling
        $orderType = $this->safe_string($params, 'orderType', 'limit');
        $isMarketOrder = ($orderType === 'market');
        // Get rounding buffer constant
        $roundingBuffer = $this->safe_integer($this->options, 'roundingBufferDecimals', 4);
        // Determine decimal precision based on $order type and $side
        $makerDecimals = 0;
        $takerDecimals = 0;
        if ($isMarketOrder) {
            // Get $market $order decimal limits for quote (USDC) and base (tokens)
            $marketOrderQuoteDecimals = $this->safe_integer($this->options, 'marketOrderQuoteDecimals', 2);
            $marketOrderBaseDecimals = $this->safe_integer($this->options, 'marketOrderBaseDecimals', 4);
            if ($isBuy) {
                // Market buy orders => $maker gives USDC (quote), $taker gives tokens (base)
                $makerDecimals = $marketOrderQuoteDecimals;
                $takerDecimals = $marketOrderBaseDecimals;
            } else {
                // Market sell orders => $maker gives tokens (base), $taker gives USDC (quote)
                $makerDecimals = $marketOrderBaseDecimals;
                $takerDecimals = $marketOrderQuoteDecimals;
            }
        } else {
            // Limit orders => use $amountDecimals for both
            $makerDecimals = $amountDecimals;
            $takerDecimals = $amountDecimals;
        }
        if ($isBuy) {
            // BUY => $maker gives USDC, wants tokens
            // Round down $size first
            $rawTakerAmt = $this->round_down($size, $sizeDecimals);
            // Round $taker amount to max decimals
            if ($this->decimal_places($rawTakerAmt) > $takerDecimals) {
                $rawTakerAmt = $this->round_down($rawTakerAmt, $takerDecimals);
            }
            // Calculate $maker amount => raw_maker_amt = raw_taker_amt * raw_price
            // Do NOT round calculated amounts - preserve full precision for accurate calculations
            // The decimal limits apply to input $size and final representation, not intermediate calculations
            $rawMakerAmt = Precise::string_mul($rawTakerAmt, $rawPrice);
            // Convert to smallest units => $maker gives USDC ($quoteDecimals), $taker gives tokens ($baseDecimals)
            $makerAmount = $this->to_token_decimals($rawMakerAmt, $quoteDecimals);
            $takerAmount = $this->to_token_decimals($rawTakerAmt, $baseDecimals);
        } else {
            // SELL => $maker gives tokens, wants USDC
            // Round down $size first
            $rawMakerAmt = $this->round_down($size, $sizeDecimals);
            // Round $maker amount to max decimals
            if ($this->decimal_places($rawMakerAmt) > $makerDecimals) {
                $rawMakerAmt = $this->round_down($rawMakerAmt, $makerDecimals);
            }
            // Calculate $taker amount => raw_taker_amt = raw_maker_amt * raw_price
            // Do NOT round calculated amounts - preserve full precision for accurate calculations
            // The decimal limits apply to input $size and final representation, not intermediate calculations
            $rawTakerAmt = Precise::string_mul($rawMakerAmt, $rawPrice);
            // Convert to smallest units => $maker gives tokens ($baseDecimals), $taker gives USDC ($quoteDecimals)
            $makerAmount = $this->to_token_decimals($rawMakerAmt, $baseDecimals);
            $takerAmount = $this->to_token_decimals($rawTakerAmt, $quoteDecimals);
        }
        $sideInt = $this->get_side($side, $params);
        $order = array(
            'salt' => (string) $salt, // uint256
            'maker' => $normalizedMaker, // address
            'signer' => $normalizedSigner, // address
            'taker' => $normalizedTaker, // address
            'tokenId' => (string) $tokenId, // uint256
            'makerAmount' => (string) $makerAmount, // uint256
            'takerAmount' => (string) $takerAmount, // uint256
            'expiration' => (string) $expiration, // uint256
            'nonce' => (string) $nonce, // uint256
            'feeRateBps' => (string) $feeRateBps, // uint256
            'side' => $sideInt, // uint8 => number (0 or 1)
            'signatureType' => $signatureType, // uint8 => number (0, 1, or 2)
        );
        $chainId = $this->safe_integer($this->options, 'chainId');
        $orderDomainName = $this->safe_string($this->options, 'orderDomainName');
        $orderDomainVersion = $this->safe_string($this->options, 'orderDomainVersion');
        $contractConfig = $this->get_contract_config($chainId);
        // Select $verifyingContract based on neg_risk status:
        // - Standard (binary) markets use CTF Exchange (exchange)
        // - Neg risk (multi-outcome) markets use Neg Risk CTF Exchange (negRiskExchange)
        // See https://github.com/Polymarket/py-clob-client/blob/main/py_clob_client/order_builder/builder.py
        // Priority => $params->negRisk > $market->info.negRisk (camelCase, Gamma API) > $market->info.neg_risk (snake_case, CLOB API) > fetch from CLOB
        $negRisk = $this->safe_bool($params, 'negRisk');
        if ($negRisk === null) {
            // Gamma API uses camelCase; CLOB orderbook uses snake_case — check both
            $negRisk = $this->safe_bool($orderMarketInfo, 'negRisk');
        }
        if ($negRisk === null) {
            $negRisk = $this->safe_bool($orderMarketInfo, 'neg_risk');
        }
        if ($negRisk === null && $tokenId !== null) {
            // Authoritative fallback => query the CLOB /neg-risk endpoint
            $negRiskResponse = $this->clob_public_get_neg_risk(array( 'token_id' => $tokenId ));
            $negRisk = $this->safe_bool($negRiskResponse, 'neg_risk');
        }
        $contractKey = 'exchange';
        if ($negRisk) {
            $contractKey = 'negRiskExchange';
        }
        $verifyingContract = $this->normalize_address($this->safe_string($contractConfig, $contractKey));
        // Domain must match exactly what server expects for $signature validation
        $domain = array(
            'name' => $orderDomainName,
            'version' => $orderDomainVersion,
            'chainId' => $chainId,
            'verifyingContract' => $verifyingContract,
        );
        // EIP-712 types for orders from https://github.com/Polymarket/clob-$order-utils/blob/main/src/exchange.order.const.ts
        $ORDER_STRUCTURE = array(
            array( 'name' => 'salt', 'type' => 'uint256' ),
            array( 'name' => 'maker', 'type' => 'address' ),
            array( 'name' => 'signer', 'type' => 'address' ),
            array( 'name' => 'taker', 'type' => 'address' ),
            array( 'name' => 'tokenId', 'type' => 'uint256' ),
            array( 'name' => 'makerAmount', 'type' => 'uint256' ),
            array( 'name' => 'takerAmount', 'type' => 'uint256' ),
            array( 'name' => 'expiration', 'type' => 'uint256' ),
            array( 'name' => 'nonce', 'type' => 'uint256' ),
            array( 'name' => 'feeRateBps', 'type' => 'uint256' ),
            array( 'name' => 'side', 'type' => 'uint8' ),
            array( 'name' => 'signatureType', 'type' => 'uint8' ),
        );
        // primary type is types[0] => 'primaryType' => 'Order'
        // EIP712Domain shouldn't be included in $messageTypes
        $messageTypes = array(
            'Order' => $ORDER_STRUCTURE,
        );
        $signature = $this->sign_typed_data($domain, $messageTypes, $order);
        $order['signature'] = $signature;
        return $order;
    }

    public function build_order(string $symbol, string $type, string $side, float $amount, ?float $price = null, $params = array ()): array {
        /**
         * build a signed order request payload from order parameters
         *
         * @see https://docs.polymarket.com/developers/CLOB/orders/create-order
         * @see https://docs.polymarket.com/developers/CLOB/orders/create-order-batch
         *
         * @param {string} $symbol unified $symbol of the $market to create an order in
         * @param {string} $type 'market' or 'limit'
         * @param {string} $side 'buy' or 'sell'
         * @param {float} $amount how much you want to trade in units of the base currency
         * @param {float} [$price] the $price at which the order is to be fulfilled, in units of the quote currency, ignored in $market orders
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @param {string} [$params->token_id] the token ID (required if $market has multiple outcomes)
         * @param {string} [$params->timeInForce] 'GTC', 'IOC', 'FOK', 'GTD' (default => 'GTC')
         * @param {string} [$params->clientOrderId] a unique id for the order
         * @param {boolean} [$params->postOnly] if true, the order will only be posted to the order book and not executed immediately
         * @param {number} [$params->expiration] $expiration timestamp in seconds (default => 30 days from now)
         * @return {array} request payload with order, $owner, $orderType, and optional fields
         */
        $market = $this->market($symbol);
        $marketInfo = $this->safe_dict($market, 'info', array());
        // Get token ID from $params or $market
        // Use $market['id'] which is the specific token ID for this outcome (YES/NO)
        // Do NOT use clobTokenIds[0] always picks the first outcome regardless of $symbol
        $tokenId = $this->safe_string($params, 'token_id');
        if ($tokenId === null) {
            $tokenId = $this->safe_string($market, 'id');
        }
        if ($tokenId === null) {
            throw new ArgumentsRequired($this->id . ' buildOrder() requires a token_id parameter for $market ' . $symbol);
        }
        // Convert CCXT $side to Polymarket $side (BUY/SELL)
        $polymarketSide = ($side === 'buy') ? 'BUY' : 'SELL';
        // Convert $amount and $price to strings
        $size = $this->number_to_string($amount);
        $priceStr = null;
        if ($type === 'limit') {
            if ($price === null) {
                throw new ArgumentsRequired($this->id . ' buildOrder() requires a $price parameter for limit orders');
            }
            $priceStr = $this->number_to_string($price);
        } elseif ($type === 'market') {
            // For $market orders, $price is optional but recommended
            // If not provided, we'll try to fetch from orderbook or use $params->marketPrice
            if ($price !== null) {
                $priceStr = $this->number_to_string($price);
            } else {
                // Try to get $price from $params->marketPrice
                $marketPrice = $this->safe_number($params, 'marketPrice');
                if ($marketPrice !== null) {
                    $priceStr = $this->number_to_string($marketPrice);
                }
            }
        }
        // Determine $orderType (at top level, not inside order object)
        // Must be determined before building orderObject to set $expiration correctly
        $orderType = $this->safe_string($params, 'timeInForce', 'GTC');
        if ($type === 'market') {
            // For $market orders, use IOC (Immediate-Or-Cancel) by default
            // IOC allows partial fills, making it more forgiving than FOK (Fill-Or-Kill)
            // Users can still override with $params->timeInForce = 'FOK' if needed
            $orderType = $this->safe_string($params, 'timeInForce', 'IOC');
        }
        // Set $expiration BEFORE signing => for non-GTD orders (GTC, FOK, FAK), $expiration must be '0'
        // Only GTD orders should have a timestamp $expiration
        // The signature must match the exact $expiration value that will be sent to the API
        // See https://docs.polymarket.com/developers/CLOB/orders/create-order#request-payload-parameters
        $orderTypeUpper = strtoupper($orderType);
        // For non-GTD orders, $expiration MUST be '0' (API requirement)
        // Override any user-provided $expiration for non-GTD orders
        $orderParams = $this->extend(array(), $params);
        if ($orderTypeUpper === 'GTD') {
            $expiration = $this->safe_integer($params, 'expiration');
            if ($expiration === null) {
                $nowSeconds = (int) floor($this->milliseconds() / 1000);
                $defaultExpirationDays = $this->safe_integer($this->options, 'defaultExpirationDays', 30);
                $expiration = $nowSeconds . ($defaultExpirationDays * 24 * 60 * 60);
            } else {
                $orderParams['expiration'] = (string) $expiration;
            }
        } else {
            // For non-GTD orders, $expiration must be 0 (will be converted to "0" string in signing)
            $orderParams['expiration'] = 0;
        }
        // Pass order $type to buildAndSignOrder for $market order special handling
        $orderParams['orderType'] = $type;
        // Build and sign the order with EIP-712 (pass $market to use fees from $market)
        $signedOrder = $this->build_and_sign_order($tokenId, $polymarketSide, $size, $priceStr, $market, $orderParams);
        // override $signedOrder types
        $signedOrder['salt'] = $this->parse_to_int($signedOrder['salt']); // integer not string
        $signedOrder['side'] = $polymarketSide; // string (BUY or SELL)
        // Get API credentials for $owner field
        $apiCredentials = $this->get_api_credentials();
        $owner = $this->safe_string($apiCredentials, 'apiKey');
        if ($owner === null) {
            throw new AuthenticationError($this->id . ' buildOrder() requires API credentials (apiKey)');
        }
        // Build request payload according to API specification
        // Top-level fields => order, $owner, $orderType
        $requestPayload = array(
            'order' => $signedOrder,
            'owner' => $owner,
            'orderType' => strtoupper($orderType),
        );
        // Add optional parameters if provided
        $clientOrderId = $this->safe_string($params, 'clientOrderId');
        if ($clientOrderId !== null) {
            $requestPayload['clientOrderId'] = $clientOrderId;
        }
        $postOnly = $this->safe_bool($params, 'postOnly', false);
        if ($postOnly) {
            $requestPayload['postOnly'] = true;
        }
        return $requestPayload;
    }

    public function create_order(string $symbol, string $type, string $side, float $amount, ?float $price = null, $params = array ()): array {
        /**
         * create a trade $order
         *
         * @see https://github.com/Polymarket/py-clob-client/blob/main/py_clob_client/client.py
         * @see https://docs.polymarket.com/developers/CLOB/orders/create-$order
         * @see https://github.com/Polymarket/clob-$order-utils
         * @see https://docs.polymarket.com/developers/CLOB/orders/create-$order#request-payload-parameters
         *
         * @param {string} $symbol unified $symbol of the $market to create an $order in
         * @param {string} $type 'market' or 'limit'
         * @param {string} $side 'buy' or 'sell'
         * @param {float} $amount how much you want to trade in units of the base currency
         * @param {float} [$price] the $price at which the $order is to be fulfilled, in units of the quote currency, ignored in $market orders
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @param {string} [$params->token_id] the token ID (required if $market has multiple outcomes)
         * @param {string} [$params->timeInForce] 'GTC', 'IOC', 'FOK', 'GTD' (default => 'GTC')
         * @param {string} [$params->clientOrderId] a unique id for the $order
         * @param {boolean} [$params->postOnly] if true, the $order will only be posted to the $order book and not executed immediately
         * @param {number} [$params->expiration] expiration timestamp in seconds (default => 30 days from now)
         * @param {number} [$params->nonce] $order nonce for batch cancellation grouping (default => 0)
         * @param {number} [$params->feeRateBps] fee rate in basis points (default => fetched from API)
         * @return {array} an ~@link https://docs.ccxt.com/#/?id=$order-structure $order structure~
         */
        $this->load_markets();
        // Ensure API credentials are generated (lazy generation)
        $this->ensure_api_credentials($params);
        // Build the $order request payload
        $requestPayload = $this->build_order($symbol, $type, $side, $amount, $price, $params);
        // Extract $clientOrderId from request payload for return value
        $clientOrderId = $this->safe_string($requestPayload, 'clientOrderId');
        // Submit $order via POST /order endpoint
        $response = $this->clob_private_post_order($this->extend($requestPayload, $params));
        // Response format:
        // {
        //     "success" => boolean,
        //     "errorMsg" => string (if error),
        //     "orderId" => string,
        //     "orderHashes" => stringarray() (if $order was marketable)
        // }
        $success = $this->safe_bool($response, 'success', true);
        if (!$success) {
            $errorMsg = $this->safe_string($response, 'errorMsg', 'Unknown error');
            throw new ExchangeError($this->id . ' createOrder() failed => ' . $errorMsg);
        }
        $orderId = $this->safe_string($response, 'orderID');
        if ($orderId === null) {
            throw new ExchangeError($this->id . ' createOrder() $response missing orderID');
        }
        $market = null;
        if ($symbol) {
            $market = $this->market($symbol);
        }
        // Combine $response with $order details from $requestPayload for parseOrder
        $orderData = $this->extend(array(
            'orderID' => $orderId,
            'clientOrderId' => $clientOrderId,
            'order' => $requestPayload['order'], // Include the signed $order for additional context
            'order_type' => $requestPayload['orderType'], // Include orderType for parseOrder
        ), $response);
        $order = $this->parse_order($orderData, $market);
        return $order;
    }

    public function create_orders(array $orders, $params = array ()): array {
        /**
         * create multiple trade $orders
         *
         * @see https://github.com/Polymarket/py-clob-client/blob/main/py_clob_client/client.py
         * @see https://docs.polymarket.com/developers/CLOB/orders/create-$order-batch
         *
         * @param {Array} $orders list of $orders to create, each $order should contain the parameters required by createOrder
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @return {array} an array of ~@link https://docs.ccxt.com/#/?id=$order-structure $order structures~
         */
        $this->load_markets();
        // Ensure API credentials are generated (lazy generation)
        $this->ensure_api_credentials($params);
        $orderRequests = array();
        $clientOrderIds = array();
        $symbols = array();
        for ($i = 0; $i < count($orders); $i++) {
            $order = $orders[$i];
            $symbol = $this->safe_string($order, 'symbol');
            if ($symbol === null) {
                throw new ArgumentsRequired($this->id . ' createOrders() requires a $symbol in each order');
            }
            $type = $this->safe_string($order, 'type');
            $side = $this->safe_string($order, 'side');
            $amount = $this->safe_number($order, 'amount');
            $price = $this->safe_number($order, 'price');
            $orderParams = $this->safe_dict($order, 'params', array());
            // Merge $order-level $params with top-level $params
            $mergedParams = $this->extend(array(), $params, $orderParams);
            // Get token_id from $order $params, $order directly, or it will be resolved in buildOrder
            $tokenId = $this->safe_string($orderParams, 'token_id') || $this->safe_string($order, 'token_id');
            if ($tokenId !== null) {
                $mergedParams['token_id'] = $tokenId;
            }
            // Get $clientOrderId from $order $params or $order directly
            $clientOrderId = $this->safe_string($orderParams, 'clientOrderId') || $this->safe_string($order, 'clientOrderId');
            if ($clientOrderId !== null) {
                $mergedParams['clientOrderId'] = $clientOrderId;
            }
            // Get $timeInForce from $order $params or $order directly
            $timeInForce = $this->safe_string($orderParams, 'timeInForce') || $this->safe_string($order, 'timeInForce');
            if ($timeInForce !== null) {
                $mergedParams['timeInForce'] = $timeInForce;
            }
            // Build the $order request payload using the shared buildOrder function
            $orderRequest = $this->build_order($symbol, $type, $side, $amount, $price, $mergedParams);
            // Store $clientOrderId from request payload for $response parsing
            $requestClientOrderId = $this->safe_string($orderRequest, 'clientOrderId');
            $clientOrderIds[] = $requestClientOrderId;
            $symbols[] = $symbol;
            $orderRequests[] = $orderRequest;
        }
        // Submit batch $orders via POST /orders endpoint
        $response = $this->clob_private_post_orders($this->extend(array( 'orders' => $orderRequests ), $params));
        // Response format => array of $order responses, each with:
        // {
        //     "success" => boolean,
        //     "errorMsg" => string (if error),
        //     "orderId" => string,
        //     "orderHashes" => stringarray() (if $order was marketable)
        // }
        $result = array();
        for ($i = 0; $i < count($response); $i++) {
            $orderResponse = $response[$i];
            $success = $this->safe_bool($orderResponse, 'success', true);
            if (!$success) {
                $errorMsg = $this->safe_string($orderResponse, 'errorMsg', 'Unknown error');
                throw new ExchangeError($this->id . ' createOrders() failed for $order ' . $i . ' => ' . $errorMsg);
            }
            $orderId = $this->safe_string($orderResponse, 'orderID');
            if ($orderId === null) {
                throw new ExchangeError($this->id . ' createOrders() $response missing orderID for $order ' . $i);
            }
            $market = null;
            if ($symbols[$i]) {
                $market = $this->market($symbols[$i]);
            }
            // Combine $response with $order details from $orderRequests for parseOrder
            $orderData = $this->extend(array(
                'orderID' => $orderId,
                'clientOrderId' => $clientOrderIds[$i],
                'order' => $orderRequests[$i]['order'], // Include the signed $order for additional context
                'order_type' => $orderRequests[$i]['orderType'], // Include orderType for parseOrder
            ), $orderResponse);
            $result[] = $this->parse_order($orderData, $market);
        }
        return $result;
    }

    public function create_market_order(string $symbol, string $side, float $amount, ?float $price = null, $params = array ()) {
        /**
         * create a market order
         * @param {string} $symbol unified $symbol of the market to create an order in
         * @param {string} $side 'buy' or 'sell'
         * @param {float} $amount how much you want to trade in units of the base currency
         * @param {float} [$price] ignored for market orders
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @return {array} an ~@link https://docs.ccxt.com/#/?id=order-structure order structure~
         */
        // Use IOC by default for market orders (allows partial fills)
        // Users can override with $params->timeInForce = 'FOK' if they need Fill-Or-Kill behavior
        return $this->create_order($symbol, 'market', $side, $amount, $price, $this->extend($params, array( 'timeInForce' => 'IOC' )));
    }

    public function cancel_order(string $id, ?string $symbol = null, $params = array ()): array {
        /**
         * cancels an open order
         *
         * @see https://github.com/Polymarket/py-clob-client/blob/main/py_clob_client/client.py
         * @see https://docs.polymarket.com/developers/CLOB/orders/cancel-order
         *
         * @param {string} $id order $id
         * @param {string} $symbol unified $symbol of the $market the order was made in
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @return {array} An ~@link https://docs.ccxt.com/#/?$id=order-structure order structure~
         */
        $this->load_markets();
        // Ensure API credentials are generated (lazy generation)
        $this->ensure_api_credentials($params);
        // Based on cancel() from py-clob-client
        // See https://github.com/Polymarket/py-clob-client/blob/main/py_clob_client/endpoints.py (CANCEL = "/order")
        // Response format => array( $canceled => stringarray(), not_canceled => array( order_id -> $reason ) )
        // See https://docs.polymarket.com/developers/CLOB/orders/cancel-order
        $response = $this->clob_private_delete_order($this->extend(array( 'order_id' => $id ), $params));
        $canceled = $this->safe_list($response, 'canceled', array());
        $notCanceled = $this->safe_dict($response, 'not_canceled', array());
        // Check if order was successfully $canceled
        $isCanceled = false;
        for ($i = 0; $i < count($canceled); $i++) {
            if ($canceled[$i] === $id) {
                $isCanceled = true;
                break;
            }
        }
        if ($isCanceled) {
            // Order was $canceled, parse order from $response data
            $market = $symbol ? $this->market($symbol) : null;
            $orderData = array(
                'id' => $id,
                'status' => 'canceled',
                'info' => $response,
            );
            return $this->parse_order($orderData, $market);
        } else {
            // Check if order is in not_canceled map
            $reason = $this->safe_string($notCanceled, $id);
            if ($reason !== null) {
                // Order couldn't be $canceled, throw error with $reason
                throw new ExchangeError($this->id . ' cancelOrder() failed => ' . $reason);
            } else {
                // Order ID not found in $response (shouldn't happen)
                throw new ExchangeError($this->id . ' cancelOrder() unexpected $response format');
            }
        }
    }

    public function cancel_orders(array $ids, ?string $symbol = null, $params = array ()): array {
        /**
         * cancel multiple $orders
         *
         * @see https://github.com/Polymarket/py-clob-client/blob/main/py_clob_client/client.py
         * @see https://docs.polymarket.com/developers/CLOB/orders/cancel-order-batch
         *
         * @param {string[]} $ids order $ids
         * @param {string} $symbol unified $symbol of the $market the $orders were made in
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @return {array} an array of ~@link https://docs.ccxt.com/#/?id=order-structure order structures~
         */
        $this->load_markets();
        // Ensure API credentials are generated (lazy generation)
        $this->ensure_api_credentials($params);
        // Based on cancel_orders() from py-clob-client
        // See https://github.com/Polymarket/py-clob-client/blob/main/py_clob_client/endpoints.py (CANCEL_ORDERS = "/orders")
        // Response format => array( $canceled => stringarray(), not_canceled => array( order_id -> reason ) )
        // See https://docs.polymarket.com/developers/CLOB/orders/cancel-order-batch
        $response = $this->clob_private_delete_orders($this->extend(array( 'order_ids' => $ids ), $params));
        $canceled = $this->safe_list($response, 'canceled', array());
        $notCanceled = $this->safe_dict($response, 'not_canceled', array());
        $market = $symbol ? $this->market($symbol) : null;
        $orders => Orderarray() = array();
        // Add $canceled $orders
        for ($i = 0; $i < count($canceled); $i++) {
            $orderId = $canceled[$i];
            $orderData = array(
                'id' => $orderId,
                'status' => 'canceled',
                'info' => $response,
            );
            $orders[] = $this->parse_order($orderData, $market);
        }
        // Verify all requested $orders are accounted for in the $response
        for ($i = 0; $i < count($ids); $i++) {
            $orderId = $ids[$i];
            $isInCanceled = false;
            for ($j = 0; $j < count($canceled); $j++) {
                if ($canceled[$j] === $orderId) {
                    $isInCanceled = true;
                    break;
                }
            }
            if (!$isInCanceled && !(is_array($notCanceled) && array_key_exists($orderId, $notCanceled))) {
                // Order ID not found in $response (unexpected)
                throw new ExchangeError($this->id . ' cancelOrders() unexpected $response format for order ' . $orderId);
            }
        }
        return $orders;
    }

    public function cancel_all_orders(?string $symbol = null, $params = array ()): array {
        /**
         * cancel all open $orders
         *
         * @see https://github.com/Polymarket/py-clob-client/blob/main/py_clob_client/client.py
         * @see https://docs.polymarket.com/developers/CLOB/orders/cancel-all-$orders
         *
         * @param {string} [$symbol] unified $market $symbol, only $orders in the $market of this $symbol are cancelled when $symbol is not null
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @return {array[]} a list of ~@link https://docs.ccxt.com/#/?id=order-structure order structures~
         */
        $this->load_markets();
        // Ensure API credentials are generated (lazy generation)
        $this->ensure_api_credentials($params);
        $response;
        if ($symbol !== null) {
            // Use cancel-$market-$orders endpoint when $symbol is provided
            // See https://docs.polymarket.com/developers/CLOB/orders/cancel-$market-$orders
            $market = $this->market($symbol);
            $marketInfo = $this->safe_dict($market, 'info', array());
            // Get condition_id ($market ID)
            $conditionId = $this->safe_string($marketInfo, 'condition_id', $market['id']);
            // Get asset_id from $market
            // Use $market['id'] which is the specific token ID for this outcome (YES/NO)
            // Do NOT use clobTokenIds[0] always picks the first outcome regardless of $symbol
            $request = array();
            if ($conditionId !== null) {
                $request['market'] = $conditionId;
            }
            $assetId = $this->safe_string($market, 'id');
            if ($assetId !== null) {
                $request['asset_id'] = $assetId;
            }
            // Response format => array( $canceled => stringarray(), not_canceled => array( order_id -> reason ) )
            $response = $this->clob_private_delete_cancel_market_orders($this->extend($request, $params));
        } else {
            // Use cancel-all endpoint when $symbol is null
            // Based on cancel_all() from py-clob-client
            // See https://github.com/Polymarket/py-clob-client/blob/main/py_clob_client/endpoints.py (CANCEL_ALL = "/cancel-all")
            // Response format => array( $canceled => stringarray(), not_canceled => array( order_id -> reason ) )
            // See https://docs.polymarket.com/developers/CLOB/orders/cancel-all-$orders
            $response = $this->clob_private_delete_cancel_all($params);
        }
        $canceled = $this->safe_list($response, 'canceled', array());
        $orderMarket = $symbol ? $this->market($symbol) : null;
        $orders => Orderarray() = array();
        // Add $canceled $orders
        for ($i = 0; $i < count($canceled); $i++) {
            $orderId = $canceled[$i];
            $orderData = array(
                'id' => $orderId,
                'status' => 'canceled',
                'info' => $response,
            );
            $orders[] = $this->parse_order($orderData, $orderMarket);
        }
        return $orders;
    }

    public function fetch_order(string $id, ?string $symbol = null, $params = array ()): array {
        /**
         * fetches information on an order made by the user
         *
         * @see https://github.com/Polymarket/py-clob-client/blob/main/py_clob_client/client.py
         * @see https://docs.polymarket.com/developers/CLOB/orders/get-order
         *
         * @param {string} $id order $id
         * @param {string} $symbol unified $symbol of the $market the order was made in
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @return {array} An ~@link https://docs.ccxt.com/#/?$id=order-structure order structure~
         */
        $this->load_markets();
        // Ensure API credentials are generated (lazy generation)
        $this->ensure_api_credentials($params);
        // Based on get_order() from py-clob-client
        // See https://github.com/Polymarket/py-clob-client/blob/main/py_clob_client/endpoints.py (GET_ORDER = "/data/order/")
        $response = $this->clob_private_get_order($this->extend(array( 'order_id' => $id ), $params));
        $market = $symbol ? $this->market($symbol) : null;
        return $this->parse_order($response, $market);
    }

    public function fetch_orders(?string $symbol = null, ?int $since = null, ?int $limit = null, $params = array ()): array {
        /**
         * fetches information on multiple orders made by the user
         *
         * @see https://github.com/Polymarket/py-clob-client/blob/main/py_clob_client/client.py
         * @see https://docs.polymarket.com/developers/CLOB/orders/get-orders
         *
         * @param {string} $symbol unified $symbol of the $market the orders were made in
         * @param {int} [$since] the earliest time in ms to fetch orders for
         * @param {int} [$limit] the maximum number of order structures to retrieve
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @param {string} [$params->id] filter orders by order $id
         * @param {string} [$params->market] filter orders by $market $id
         * @param {string} [$params->asset_id] filter orders by asset $id (alias token_id)
         * @return {array[]} a list of ~@link https://docs.ccxt.com/#/?$id=order-structure order structures~
         */
        $this->load_markets();
        $this->ensure_api_credentials($params);
        $request = array();
        if ($symbol !== null) {
            $market = $this->market($symbol);
            $marketInfo = $this->safe_dict($market, 'info', array());
            // Filter by condition_id ($market) to get all orders for this $market
            // This is more appropriate than filtering by asset_id alone, $market can have multiple outcomes
            $conditionId = $this->safe_string($marketInfo, 'condition_id', $market['id']);
            if ($conditionId !== null) {
                $request['market'] = $conditionId;
            }
            // Also include asset_id for backward compatibility and more specific filtering
            // Use $market['id'] which is the specific token ID for this outcome (YES/NO)
            // Do NOT use clobTokenIds[0] always picks the first outcome regardless of $symbol
            $assetId = $this->safe_string($market, 'id');
            if ($assetId !== null) {
                // The Polymarket L2 getOpenOrders() endpoint filters by asset_id
                $request['asset_id'] = $assetId;
                // Keep backward compatibility for legacy token_id usage
                $request['token_id'] = $assetId;
            }
        }
        $id = $this->safe_string($params, 'id');
        if ($id !== null) {
            $request['id'] = $id;
        }
        $marketId = $this->safe_string($params, 'market');
        if ($marketId !== null) {
            $request['market'] = $marketId;
        }
        $assetId = $this->safe_string_2($params, 'asset_id', 'token_id');
        if ($assetId !== null) {
            $request['asset_id'] = $assetId;
            $request['token_id'] = $assetId;
        }
        $initialCursor = $this->safe_string($this->options, 'initialCursor');
        $endCursor = $this->safe_string($this->options, 'endCursor');
        $nextCursor = $initialCursor;
        $ordersResponse => anyarray() = array();
        while (true) {
            $response = $this->clob_private_get_orders($this->extend($request, array( 'next_cursor' => $nextCursor ), $params));
            $data = $this->safe_list($response, 'data', array());
            $ordersResponse = $this->array_concat($ordersResponse, $data);
            if ($limit !== null && strlen($ordersResponse) >= $limit) {
                break;
            }
            $nextCursor = $this->safe_string($response, 'next_cursor');
            if ($nextCursor === null || $nextCursor === $endCursor) {
                break;
            }
        }
        $orderMarket = $symbol ? $this->market($symbol) : null;
        return $this->parse_orders($ordersResponse, $orderMarket, $since, $limit);
    }

    public function fetch_open_orders(?string $symbol = null, ?int $since = null, ?int $limit = null, $params = array ()): array {
        /**
         * fetch all unfilled currently open orders
         * @param {string} $symbol unified $symbol of the market to fetch open orders for
         * @param {int} [$since] the earliest time in ms to fetch open orders for
         * @param {int} [$limit] the maximum number of open order structures to retrieve
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @return {array[]} a list of ~@link https://docs.ccxt.com/#/?id=order-structure order structures~
         */
        return $this->fetch_orders($symbol, $since, $limit, $params);
    }

    public function parse_order(array $order, ?array $market = null): array {
        /**
         * parses an $order from the exchange response format
         * @param {array} $order order response from the exchange
         * @param {array} [$market] $market structure
         * @return {array} an ~@link https://docs.ccxt.com/#/?$id=$order-structure $order structure~
         */
        // Handle createOrder/createOrders response format:
        // {
        //   "success" => boolean,
        //   "errorMsg" => string (if error),
        //   "orderID" => string,
        //   "orderHashes" => stringarray() (if $order was marketable)
        // }
        // Or fetchOrder response format (OpenOrder interface):
        // {
        //   $id => string;
        //   $status => string;
        //   owner => string;
        //   maker_address => string;
        //   $market => string;
        //   asset_id => string;
        //   $side => string;
        //   original_size => string;
        //   size_matched => string;
        //   $price => string;
        //   associate_trades => stringarray();
        //   outcome => string;
        //   created_at => number; // seconds
        //   expiration => string;
        //   order_type => string;
        // }
        $id = $this->safe_string($order, 'id');
        // Handle createOrder response format (has orderID instead of $id)
        if ($id === null) {
            $id = $this->safe_string($order, 'orderID');
        }
        $marketId = $this->safe_string($order, 'market');
        $assetId = $this->safe_string($order, 'asset_id');
        if ($market === null && $marketId !== null) {
            $market = $this->safe_market_with_fallback($marketId, null, $order);
        }
        $symbol = null;
        if ($market !== null && $market['symbol'] !== null) {
            $symbol = $market['symbol'];
        } elseif ($assetId !== null) {
            $symbol = $assetId;
        }
        // Handle createOrder response - get $side from $order object if available
        $sideStr = $this->safe_string_lower($order, 'side');
        // If $side is not in $order, try to get it from the $order object passed in createOrder
        if ($sideStr === null) {
            $orderObj = $this->safe_dict($order, 'order');
            if ($orderObj !== null) {
                $sideStr = $this->safe_string_lower($orderObj, 'side');
            }
        }
        $side = ($sideStr === 'buy' || $sideStr === 'sell') ? $sideStr : null;
        $orderType = $this->safe_string($order, 'order_type');
        // Handle createOrder response - get $orderType from $order object if available
        if ($orderType === null) {
            $orderObj = $this->safe_dict($order, 'order');
            if ($orderObj !== null) {
                $orderType = $this->safe_string($orderObj, 'orderType');
            }
            // Also check at top level (from requestPayload)
            if ($orderType === null) {
                $orderType = $this->safe_string($order, 'orderType');
            }
        }
        // Normalize $orderType to lowercase for consistent parsing
        if ($orderType !== null) {
            $orderType = strtolower($orderType);
        }
        // Amounts
        $amount = $this->safe_number($order, 'original_size');
        // Handle createOrder response - get $amount from $order object if available
        if ($amount === null) {
            $orderObj = $this->safe_dict($order, 'order');
            if ($orderObj !== null) {
                $amount = $this->safe_number($orderObj, 'size');
            }
        }
        $filled = $this->safe_number($order, 'size_matched');
        $remaining = $this->safe_number($order, 'remaining_size');
        if ($remaining === null && $amount !== null && $filled !== null) {
            $remaining = $amount - $filled;
        }
        // Price
        $price = $this->safe_number($order, 'price');
        // Handle createOrder response - get $price from $order object if available
        if ($price === null) {
            $orderObj = $this->safe_dict($order, 'order');
            if ($orderObj !== null) {
                $price = $this->safe_number($orderObj, 'price');
            }
        }
        // Status
        $statusStr = $this->safe_string($order, 'status', '');
        $status = $this->parse_order_status($statusStr);
        // Timestamps (created_at is seconds)
        $createdAt = $this->safe_integer($order, 'created_at');
        $timestamp = ($createdAt !== null) ? $createdAt * 1000 : null;
        // Get $clientOrderId from $order or from the $order object
        $clientOrderId = $this->safe_string($order, 'clientOrderId');
        if ($clientOrderId === null) {
            $orderObj = $this->safe_dict($order, 'order');
            if ($orderObj !== null) {
                $clientOrderId = $this->safe_string($orderObj, 'clientOrderId');
            }
        }
        // No explicit updated_at in interface; leave lastTradeTimestamp null
        return $this->safe_order(array(
            'id' => $id,
            'clientOrderId' => $clientOrderId,
            'info' => $order,
            'timestamp' => $timestamp,
            'datetime' => $timestamp ? $this->iso8601($timestamp) : null,
            'lastTradeTimestamp' => null,
            'status' => $status,
            'symbol' => $symbol,
            'type' => $this->parse_order_type($orderType),
            'timeInForce' => $this->parse_time_in_force($orderType),
            'side' => $side,
            'price' => $price,
            'amount' => $amount,
            'cost' => null,
            'average' => null,
            'filled' => $filled,
            'remaining' => $remaining,
            'fee' => null,
        ), $market);
    }

    public function parse_order_status(?string $status): ?string {
        /**
         * parse the $status of an order
         * @param {string} $status order $status from exchange
         * @return {string} a unified order $status
         */
        if ($status === null || $status === '') {
            return 'open'; // Default to 'open' if no $status is provided
        }
        $statuses = array(
            // https://docs.polymarket.com/developers/CLOB/orders/create-order#$status
            'matched' => 'closed',   // order placed and matched with an existing resting order
            'live' => 'open',         // order placed and resting on the book
            'delayed' => 'open',      // order marketable, but subject to matching delay
            'unmatched' => 'open',    // order marketable, but failure delaying, placement successful
            'canceled' => 'canceled', // CCXT unified $status for canceled orders
            'canceled_market_resolved' => 'canceled', // order voided because the market resolved before it was filled
            'invalid' => 'rejected',
        );
        $normalizedStatus = strtolower($status);
        return $this->safe_string($statuses, $normalizedStatus, $normalizedStatus);
    }

    public function parse_order_type(?string $type): ?string {
        $types = array(
            'fok' => 'market', // Fill-Or-Kill => market order
            'fak' => 'market', // Fill-And-Kill => market order
            'ioc' => 'market', // Immediate-Or-Cancel => market order
            'gtc' => 'limit', // Good-Til-Cancelled => limit order
            'gtd' => 'limit', // Good-Til-Date => limit order
        );
        return $this->safe_string($types, $type, 'limit');
    }

    public function parse_time_in_force(?string $timeInForce): ?string {
        if ($timeInForce === null) {
            return null;
        }
        $timeInForces = array(
            'fok' => 'FOK', // Fill-Or-Kill
            'fak' => 'FAK', // Fill-And-Kill
            'ioc' => 'IOC', // Immediate-Or-Cancel
            'gtc' => 'GTC', // Good-Til-Cancelled
            'gtd' => 'GTD', // Good-Til-Date
        );
        $normalized = strtolower($timeInForce);
        $mapped = $this->safe_string($timeInForces, $normalized);
        return $mapped !== null ? $mapped : strtoupper($timeInForce);
    }

    public function fetch_positions(?array $symbols = null, $params = array ()): array {
        /**
         * fetches the current user $positions
         * @param {string[]} [$symbols] list of unified market $symbols
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @param {string} [$params->userAddress] user wallet address (defaults to getProxyWalletAddress())
         * @return {array[]} a list of ~@link https://docs.ccxt.com/#/?id=position-structure position structures~
         */
        $this->load_markets();
        $userAddress = $this->safe_string($params, 'userAddress');
        $response = $this->get_user_positions($userAddress, $params);
        // Response format => array of position objects
        // {
        //   "proxyWallet" => "0x...",
        //   "asset" => "0x...",
        //   "conditionId" => "0x...",
        //   "size" => "123.45",
        //   "avgPrice" => "0.65",
        //   "initialValue" => "80.24",
        //   "currentValue" => "85.50",
        //   "cashPnl" => "5.26",
        //   "percentPnl" => "6.55",
        //   ...
        // }
        $positions = (gettype($response) === 'array' && array_keys($response) === array_keys(array_keys($response))) ? $response : array();
        return $this->parse_positions($positions, $symbols);
    }

