    public function fetch_user_closed_positions(string $userId, ?array $symbols = null, $params = array ()): array {
        /**
         * fetches the closed user $positions
         * @param {string} $userId user ID
         * @param {string[]} [$symbols] list of unified market $symbols
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @param {string} [$params->userAddress] user wallet address (defaults to getProxyWalletAddress())
         * @return {array[]} a list of ~@link https://docs.ccxt.com/#/?id=position-structure position structures~
         */
        $this->load_markets();
        $response = $this->get_user_closed_positions($userId, $params);
        // Response format => array of position objects
        // {
        //   "proxyWallet" => "0x...",
        //   "asset" => "0x...",
        //   "conditionId" => "0x...",
        //   "size" => "123.45",
        //   "avgPrice" => "0.65",
        //   "initialValue" => "80.24",
        //   "currentValue" => "85.50",
        //   "cashPnl" => "5.26",
        //   "percentPnl" => "6.55",
        //   ...
        // }
        $positions = (gettype($response) === 'array' && array_keys($response) === array_keys(array_keys($response))) ? $response : array();
        return $this->parse_positions($positions, $symbols);
    }

    public function safe_market_with_fallback(string $marketId, ?array $market = null, ?array $metadata = null): array {
        /**
         * Safely get a $market by ID, with fallback to synthetic $market for missing/closed markets
         * @param {string} $marketId Market ID (asset ID, clobTokenId, or symbol) to look up
         * @param {array} [$market] Optional pre-existing $market structure
         * @param {array} [$metadata] Optional $metadata (position, order, etc.) containing $market info
         * @return {array} Market structure (from marketsById, synthetic, or minimal)
         */
        try {
            $market = $this->safe_market($marketId, $market);
            // Check if $market was actually found in markets_by_id
            if ($this->markets_by_id !== null && $marketId in $this->markets_by_id) {
                return $market; // Market found, return it
            }
        } catch (Exception $e) {
            // safeMarket can raise ArgumentsRequired for ambiguous markets
            // In this case, we'll try to create synthetic or return minimal structure
            if ($e instanceof ArgumentsRequired) {
                $market = null
            } else {
                // Re-raise other exceptions
                throw $e;
            }
        }
        // Market not found in markets_by_id - if we have $metadata, try to create synthetic $market
        if ($metadata !== null) {
            $conditionId = $this->safe_string($metadata, 'conditionId');
            $slug = $this->safe_string($metadata, 'slug');
            if ($conditionId !== null || $slug !== null) {
                return $this->create_synthetic_closed_market($metadata, $marketId);
            }
        }
        // No $metadata or can't create synthetic - return minimal structure from safeMarket
        return $this->safe_market($marketId, $market);
    }

    public function create_synthetic_closed_market(array $position, string $asset): array {
        /**
         * Create a synthetic market structure for a closed/expired market
         * @param {array} $position position response from the exchange
         * @param {string} $asset asset ID
         * @return {array} synthetic market structure
         */
        $conditionId = $this->safe_string($position, 'conditionId');
        $slug = $this->safe_string($position, 'slug');
        $title = $this->safe_string($position, 'title');
        $outcome = $this->safe_string($position, 'outcome');
        $endDate = $this->safe_string($position, 'endDate');
        // Use $slug or $conditionId
        $baseId = $slug || $conditionId || $asset;
        $quoteId = $this->safe_string($this->options, 'defaultCollateral', 'USDC');
        // Parse $endDate for $symbol construction
        $expiry = null;
        if ($endDate !== null) {
            try {
                if (mb_strpos($endDate, 'T') !== false || mb_strpos($endDate, 'Z') !== false) {
                    $expiry = $this->parse8601($endDate);
                } else {
                    $expiry = $this->parse8601($endDate . 'T00:00:00Z');
                }
            } catch (Exception $e) {
                $expiry = null
            }
        }
        // Far future if no date
        $ymd = '999999';
        if ($expiry !== null) {
            $ymd = $this->yymmdd($expiry);
        }
        $optionType = 'UNKNOWN';
        if ($outcome !== null) {
            $optionType = $this->parse_option_type($outcome);
        }
        $symbol = $baseId . '/' . $quoteId . ':' . $quoteId . '-' . $ymd . '-0-' . $optionType;
        return $this->safe_market_structure(array(
            'id' => $asset,
            'symbol' => $symbol,
            'base' => $baseId,
            'quote' => $quoteId,
            'settle' => $quoteId,
            'baseId' => $baseId,
            'quoteId' => $quoteId,
            'type' => 'option',
            'spot' => false,
            'margin' => false,
            'swap' => false,
            'future' => false,
            'option' => true,
            'active' => false, // Mark since it's closed
            'contract' => true,
            'linear' => true,
            'precision' => array(
                'amount' => 6, // https://github.com/Polymarket/clob-client/blob/main/src/config.ts
                'price' => 6, // https://github.com/Polymarket/clob-client/blob/main/src/config.ts
            ),
            'limits' => array(
                'leverage' => array(
                    'min' => null,
                    'max' => null,
                ),
                'amount' => array(
                    'min' => 5, // Minimum order size
                    'max' => null,
                ),
                'price' => array(
                    'min' => 1e-6, // Prediction markets are >0 and <1
                    'max' => 1, // Prediction markets are 0-1
                ),
                'cost' => array(
                    'min' => null,
                    'max' => null,
                ),
            ),
            'info' => array(
                'conditionId' => $conditionId,
                'slug' => $slug,
                'title' => $title,
                'outcome' => $outcome,
                'endDate' => $endDate,
                'closed' => true,
            ),
        ));
    }

    public function parse_position(array $position, ?array $market = null): array {
        /**
         * parses a $position from the exchange response format
         * @param {array} $position position response from the exchange
         * @param {array} [$market] $market structure
         * @return {array} a ~@link https://docs.ccxt.com/#/?id=$position-structure $position structure~
         */
        // Response format from getUserPositions:
        // {
        //   "proxyWallet" => "0x56687bf447db6ffa42ffe2204a05edaa20f55839",
        //   "asset" => "<string>",
        //   "conditionId" => "0xdd22472e552920b8438158ea7238bfadfa4f736aa4cee91a6b86c39ead110917",
        //   "size" => 123,
        //   "avgPrice" => 123,
        //   "initialValue" => 123,
        //   "currentValue" => 123,
        //   "cashPnl" => 123,
        //   "percentPnl" => 123,
        //   "totalBought" => 123,
        //   "realizedPnl" => 123,
        //   "percentRealizedPnl" => 123,
        //   "curPrice" => 123,
        //   "redeemable" => true,
        //   "mergeable" => true,
        //   "title" => "<string>",
        //   "slug" => "<string>",
        //   "icon" => "<string>",
        //   "eventSlug" => "<string>",
        //   "outcome" => "<string>",
        //   "outcomeIndex" => 123,
        //   "oppositeOutcome" => "<string>",
        //   "oppositeAsset" => "<string>",
        //   "endDate" => "<string>",
        //   "negativeRisk" => true,
        //   "timestamp" => 123
        // }
        $conditionId = $this->safe_string($position, 'conditionId');
        $asset = $this->safe_string($position, 'asset');
        $proxyWallet = $this->safe_string($position, 'proxyWallet');
        $totalBought = $this->safe_number($position, 'totalBought');
        $realizedPnl = $this->safe_number($position, 'realizedPnl');
        $percentRealizedPnl = $this->safe_number($position, 'percentRealizedPnl');
        $curPrice = $this->safe_number($position, 'curPrice');
        $redeemable = $this->safe_bool($position, 'redeemable');
        $mergeable = $this->safe_bool($position, 'mergeable');
        $title = $this->safe_string($position, 'title');
        $slug = $this->safe_string($position, 'slug');
        $icon = $this->safe_string($position, 'icon');
        $eventSlug = $this->safe_string($position, 'eventSlug');
        $outcome = $this->safe_string($position, 'outcome');
        $outcomeIndex = $this->safe_integer($position, 'outcomeIndex');
        $oppositeOutcome = $this->safe_string($position, 'oppositeOutcome');
        $oppositeAsset = $this->safe_string($position, 'oppositeAsset');
        $endDate = $this->safe_string($position, 'endDate');
        $negativeRisk = $this->safe_bool($position, 'negativeRisk');
        $timestamp = $this->safe_integer($position, 'timestamp');
        // Get $market with automatic fallback for closed markets
        $market = $this->safe_market_with_fallback($asset, $market, $position);
        $symbol = $market['symbol'];
        $sizeString = $this->safe_string($position, 'size', '0');
        $contracts = $this->parse_number($sizeString);
        $side = null;
        if ($contracts !== null) {
            if ($contracts > 0) {
                $side = 'long';
            } elseif ($contracts < 0) {
                $side = 'short';
            }
        }
        $avgPrice = $this->safe_number($position, 'avgPrice');
        $currentValue = $this->safe_number($position, 'currentValue');
        $initialValue = $this->safe_number($position, 'initialValue');
        $cashPnl = $this->safe_number($position, 'cashPnl');
        $percentPnl = $this->safe_number($position, 'percentPnl');
        // Calculate unrealized PnL ($cashPnl is already the unrealized PnL)
        $unrealizedPnl = $cashPnl;
        // Calculate $notional value (current value of the $position)
        $notional = $currentValue;
        // Calculate $collateral (initial value invested)
        $collateral = $initialValue;
        // Extract margin mode, default to 'cross' if not available
        $marginMode = $this->safe_string($position, 'marginMode', 'cross');
        $isIsolated = ($marginMode === 'isolated');
        // For now $leverage is not supported by Polymarket
        $leverage = $this->safe_number($position, 'leverage', 1);
        // Build extended info object with parsed values
        $extendedInfo = $this->extend($position, array(
            'proxyWallet' => $proxyWallet,
            'totalBought' => $totalBought,
            'realizedPnl' => $realizedPnl,
            'percentRealizedPnl' => $percentRealizedPnl,
            'curPrice' => $curPrice,
            'redeemable' => $redeemable,
            'mergeable' => $mergeable,
            'title' => $title,
            'slug' => $slug,
            'icon' => $icon,
            'eventSlug' => $eventSlug,
            'outcome' => $outcome,
            'outcomeIndex' => $outcomeIndex,
            'oppositeOutcome' => $oppositeOutcome,
            'oppositeAsset' => $oppositeAsset,
            'endDate' => $endDate,
            'negativeRisk' => $negativeRisk,
            'timestamp' => $timestamp,
        ));
        return $this->safe_position(array(
            'info' => $extendedInfo,
            'id' => $asset,
            'symbol' => $symbol,
            'notional' => $notional,
            'marginMode' => $marginMode,
            'isolated' => $isIsolated,
            'liquidationPrice' => null,
            'entryPrice' => $avgPrice,
            'unrealizedPnl' => $unrealizedPnl,
            'percentage' => $percentPnl,
            'contracts' => $contracts,
            'contractSize' => null,
            'markPrice' => $curPrice,
            'side' => $side,
            'hedged' => null,
            'timestamp' => $timestamp,
            'datetime' => $this->iso8601($timestamp),
            'initialMarginPercentage' => null,
            'maintenanceMargin' => null,
            'maintenanceMarginPercentage' => null,
            'collateral' => $collateral,
            'initialMargin' => $initialValue,
            'leverage' => $leverage,
            'realizedPnl' => $realizedPnl,
        ));
    }

    public function fetch_time($params = array ()): ?int {
        /**
         * fetches the current integer $timestamp in milliseconds from the exchange server
         *
         * @see https://github.com/Polymarket/py-clob-client/blob/main/py_clob_client/client.py#L178
         *
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @return {int} the current integer $timestamp in milliseconds from the exchange server
         */
        // Based on get_server_time() from py-clob-client
        // See https://github.com/Polymarket/py-clob-client/blob/main/py_clob_client/client.py#L178
        $response = $this->clob_public_get_time($params);
        // Response format => $timestamp in seconds (Unix $timestamp)
        // Convert to milliseconds for CCXT standard
        $timestamp = $this->safe_integer($response, 'timestamp');
        if ($timestamp !== null) {
            return $timestamp * 1000; // Convert seconds to milliseconds
        }
        // Fallback => if $response is just a number
        if ((is_float($response) || is_int($response))) {
            return $response * 1000;
        }
        // Fallback => use current time if server time not available
        return $this->milliseconds();
    }

    public function fetch_status($params = array ()) {
        /**
         * the latest known information on the availability of the exchange API
         *
         * @see https://github.com/Polymarket/py-clob-client/blob/main/py_clob_client/client.py#L170
         *
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @return {array} a ~@link https://docs.ccxt.com/#/?id=exchange-status-structure status structure~
         */
        // Based on get_ok() from py-clob-client
        // See https://github.com/Polymarket/py-clob-client/blob/main/py_clob_client/client.py#L170
        try {
            $this->clob_public_get_ok($params);
            return array(
                'status' => 'ok',
                'updated' => null,
                'eta' => null,
                'url' => null,
            );
        } catch (Exception $e) {
            return array(
                'status' => 'error',
                'updated' => null,
                'eta' => null,
                'url' => null,
            );
        }
    }

    public function fetch_trading_fee(string $symbol, $params = array ()): array {
        /**
         * fetches the trading $fee for a $market
         *
         * @see https://github.com/Polymarket/py-clob-client/blob/main/py_clob_client/client.py
         *
         * @param {string} $symbol unified $symbol of the $market to fetch the $fee for
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @param {string} [$params->token_id] the token ID (required if not in $market info)
         * @return {array} a ~@link https://docs.ccxt.com/#/?id=$fee-structure $fee structure~
         */
        $this->load_markets();
        $market = $this->market($symbol);
        $marketInfo = $this->safe_dict($market, 'info', array());
        // Get token ID from $params or $market
        // Use $market['id'] which is the specific token ID for this outcome (YES/NO)
        // Do NOT use clobTokenIds[0] always picks the first outcome regardless of $symbol
        $tokenId = $this->safe_string($params, 'token_id');
        if ($tokenId === null) {
            $tokenId = $this->safe_string($market, 'id');
        }
        if ($tokenId === null) {
            throw new ArgumentsRequired($this->id . ' fetchTradingFee() requires a token_id parameter for $market ' . $symbol);
        }
        // Based on get_fee_rate() from py-clob-client
        // See https://github.com/Polymarket/py-clob-client/blob/main/py_clob_client/client.py
        $response = $this->clob_public_get_fee_rate($this->extend(array( 'token_id' => $tokenId ), $params));
        // Response format => array("fee_rate" => "0.02") or array("fee_rate_bps" => 200) (basis points)
        $feeRate = $this->safe_string($response, 'fee_rate');
        $feeRateBps = $this->safe_integer($response, 'fee_rate_bps');
        $maker = null;
        $taker = null;
        if ($feeRate !== null) {
            $fee = $this->parse_number($feeRate);
            $maker = $fee;
            $taker = $fee;
        } elseif ($feeRateBps !== null) {
            // Convert basis points to percentage (200 bps = 2% = 0.02)
            $fee = $this->parse_number($feeRateBps) / 10000;
            $maker = $fee;
            $taker = $fee;
        } else {
            // Default $fee from describe() if not available
            $maker = $this->safe_number($this->fees['trading'], 'maker');
            $taker = $this->safe_number($this->fees['trading'], 'taker');
        }
        // Ensure we have valid numbers (fallback to default if null)
        $makerFee = $maker !== null ? $maker : $this->parse_number('0.02');
        $takerFee = $taker !== null ? $taker : $this->parse_number('0.02');
        $result => TradingFeeInterface = array(
            'info' => $response,
            'symbol' => $symbol,
            'maker' => $makerFee,
            'taker' => $takerFee,
            'percentage' => true,
            'tierBased' => false,
        );
        return $result;
    }

    public function fetch_open_interest(string $symbol, $params = array ()) {
        /**
         * retrieves the open interest of a $market
         *
         * @see https://docs.polymarket.com/api-reference/misc/get-open-interest
         *
         * @param {string} $symbol unified CCXT $market $symbol
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @return {array} an open interest structurearray(@link https://docs.ccxt.com/#/?id=open-interest-structure)
         */
        $this->load_markets();
        $market = $this->market($symbol);
        $marketInfo = $this->safe_dict($market, 'info', array());
        $conditionId = $this->safe_string($marketInfo, 'condition_id', $market['id']);
        // API expects $market of condition IDs
        $request = array(
            'market' => array( $conditionId ),
        );
        $response = $this->data_public_get_open_interest($this->extend($request, $params));
        return $this->parse_open_interest($response, $market);
    }

    public function parse_open_interest(array $interest, ?array $market = null) {
        /**
         * parses open $interest data from the exchange response format
         * @param {array} $interest open $interest data from the exchange
         * @param {array} [$market] the $market this open $interest is for
         * @return {array} an open $interest structurearray(@link https://docs.ccxt.com/#/?id=open-$interest-structure)
         */
        // Polymarket Data API /oi response format
        // Response is an array of objects with $market (condition ID) and value
        // Example response structure:
        // array(
        //   {
        //     "market" => "0xdd22472e552920b8438158ea7238bfadfa4f736aa4cee91a6b86c39ead110917",
        //     "value" => 123
        //   }
        // )
        $timestamp = $this->milliseconds();
        // Handle array response
        $openInterestData = array();
        if ((gettype($interest) === 'array' && array_keys($interest) === array_keys(array_keys($interest)))) {
            // For single symbol query, get the first item
            if (strlen($interest) > 0) {
                $openInterestData = $interest[0];
            }
        } elseif (gettype($interest) === 'array' && $interest !== null) {
            // Fallback => handle object response if API changes
            $openInterestData = $interest;
        }
        // Extract open $interest value from the response
        // API returns "value" field which represents the open $interest value
        $openInterestValue = $this->safe_number($openInterestData, 'value', 0);
        // For Polymarket, value is typically in USDC, so we use it amount and value
        // If we need to distinguish, we could parse additional fields if available
        return $this->safe_open_interest(array(
            'symbol' => $market ? $market['symbol'] : null,
            'openInterestAmount' => $openInterestValue, // Using value since API only provides value
            'openInterestValue' => $openInterestValue,
            'timestamp' => $timestamp,
            'datetime' => $this->iso8601($timestamp),
            'info' => $interest,
        ), $market);
    }

    public function fetch_my_trades(?string $symbol = null, ?int $since = null, ?int $limit = null, $params = array ()): array {
        /**
         * fetch all trades made by the user
         *
         * @see https://github.com/Polymarket/py-clob-client/blob/main/py_clob_client/client.py
         *
         * @param {string} $symbol unified $symbol of the $market to fetch trades for
         * @param {int} [$since] the earliest time in ms to fetch trades for
         * @param {int} [$limit] the maximum number of trades structures to retrieve
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @param {string} [$params->market] filter trades by $market (condition_id)
         * @param {string} [$params->asset_id] filter trades by asset ID
         * @param {string} [$params->id] filter by trade $id
         * @param {string} [$params->maker_address] filter by maker address
         * @param {string} [$params->before] pagination cursor (see API docs)
         * @param {string} [$params->after] pagination cursor (see API docs)
         * @param {string} [$params->next_cursor] pagination cursor (default => "MA==")
         * @return {Trade[]} a list of ~@link https://docs.ccxt.com/#/?$id=trade-structure trade structures~
         */
        $this->load_markets();
        // Ensure API credentials are generated (lazy generation)
        $this->ensure_api_credentials($params);
        $request = array();
        $market = null;
        if ($symbol !== null) {
            $market = $this->market($symbol);
            $marketInfo = $this->safe_dict($market, 'info', array());
            // Filter by condition_id ($market) to get all trades for this $market
            // Don't automatically add asset_id filter would restrict to only one outcome
            $conditionId = $this->safe_string($marketInfo, 'condition_id', $this->safe_string($market, 'id'));
            if ($conditionId !== null) {
                $request['market'] = $conditionId;
            }
        }
        $tokenId = $this->safe_string($params, 'token_id');
        if ($tokenId !== null) {
            $request['asset_id'] = $tokenId;
        }
        $marketId = $this->safe_string($params, 'market');
        if ($marketId !== null) {
            $request['market'] = $marketId;
        }
        $assetId = $this->safe_string_2($params, 'asset_id', 'assetId');
        if ($assetId !== null) {
            $request['asset_id'] = $assetId;
        }
        $id = $this->safe_string($params, 'id');
        if ($id !== null) {
            $request['id'] = $id;
        }
        $makerAddress = $this->safe_string_2($params, 'maker_address', 'makerAddress');
        if ($makerAddress !== null) {
            $request['maker_address'] = $makerAddress;
        }
        $before = $this->safe_string($params, 'before');
        if ($before !== null) {
            $request['before'] = $before;
        }
        $after = $this->safe_string($params, 'after');
        if ($after !== null) {
            $request['after'] = $after;
        }
        if ($since !== null) {
            // Map ccxt $since to Polymarket's "after" cursor using seconds
            $request['after'] = $this->number_to_string((int) floor($since / 1000));
        }
        if ($limit !== null) {
            $request['limit'] = $limit;
        }
        $results => anyarray() = array();
        $initialCursor = $this->safe_string($this->options, 'initialCursor');
        $endCursor = $this->safe_string($this->options, 'endCursor');
        $next_cursor = $initialCursor;
        while ($next_cursor !== $endCursor) {
            $response = $this->clob_private_get_trades($this->extend($request, array( 'next_cursor' => $next_cursor ), $params));
            $next_cursor = $this->safe_string($response, 'next_cursor', $endCursor);
            $data = $this->safe_list($response, 'data', array()) || array();
            $results = $this->array_concat($results, $data);
            if ($limit !== null && strlen($results) >= $limit) {
                break;
            }
        }
        return $this->parse_trades($results, $market, $since, $limit);
    }

    public function fetch_user_trades(string $user, ?string $symbol = null, ?int $since = null, ?int $limit = null, $params = array ()): array {
        /**
         * fetch trades for a specific $user
         *
         * @see https://docs.polymarket.com/api-reference/core/get-trades-for-a-$user-or-markets
         *
         * @param {string} $user user address (0x-prefixed, 40 hex chars)
         * @param {string} [$symbol] unified $symbol of the $market to fetch trades for
         * @param {int} [$since] timestamp in ms of the earliest trade to fetch
         * @param {int} [$limit] the maximum amount of trades to fetch (default => 100, max => 10000)
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @param {int} [$params->offset] $offset for pagination (default => 0, max => 10000)
         * @param {boolean} [$params->takerOnly] if true, returns only trades where the $user is the taker (default => true)
         * @param {string} [$params->side] filter by $side => 'BUY' or 'SELL'
         * @param {string[]} [$params->market] comma-separated list of condition IDs (mutually exclusive with $symbol)
         * @param {int[]} [$params->eventId] comma-separated list of event IDs (mutually exclusive with $market)
         * @return {Trade[]} a list of ~@link https://docs.ccxt.com/#/?id=trade-structure trade structures~
         */
        $this->load_markets();
        $request = array(
            'user' => $user,
        );
        $market = null;
        if ($symbol !== null) {
            $market = $this->market($symbol);
            $marketInfo = $this->safe_dict($market, 'info', array());
            $conditionId = $this->safe_string($marketInfo, 'condition_id', $market['id']);
            $request['market'] = array( $conditionId );
        }
        $marketParam = $this->safe_value($params, 'market');
        if ($marketParam !== null) {
            // Convert to array if it's a string or single value
            if ((gettype($marketParam) === 'array' && array_keys($marketParam) === array_keys(array_keys($marketParam)))) {
                $request['market'] = $marketParam;
            } else {
                $request['market'] = array( $marketParam );
            }
        }
        $eventId = $this->safe_value($params, 'eventId');
        if ($eventId !== null) {
            if ((gettype($eventId) === 'array' && array_keys($eventId) === array_keys(array_keys($eventId)))) {
                $request['eventId'] = $eventId;
            } else {
                $request['eventId'] = array( $eventId );
            }
        }
        if ($limit !== null) {
            $request['limit'] = min ($limit, 10000); // Cap at max 10000
        }
        $offset = $this->safe_integer($params, 'offset');
        if ($offset !== null) {
            $request['offset'] = $offset;
        }
        $takerOnly = $this->safe_bool($params, 'takerOnly', true);
        $request['takerOnly'] = $takerOnly;
        $side = $this->safe_string_upper($params, 'side');
        if ($side !== null) {
            $request['side'] = $side;
        }
        $response = $this->data_public_get_trades($this->extend($request, $this->omit($params, array( 'market', 'eventId', 'offset', 'takerOnly', 'side' ))));
        $tradesData = array();
        if ((gettype($response) === 'array' && array_keys($response) === array_keys(array_keys($response)))) {
            $tradesData = $response;
        } else {
            $dataList = $this->safe_list($response, 'data', array());
            if ($dataList !== null) {
                $tradesData = $dataList;
            }
        }
        return $this->parse_trades($tradesData, $market, $since, $limit);
    }

    public function fetch_balance($params = array ()) {
        /**
         * fetches $balance and $allowance for the authenticated user
         *
         * @see https://github.com/Polymarket/py-clob-client/blob/main/py_clob_client/client.py
         * @see https://docs.polymarket.com/developers/CLOB/clients/methods-l2#getbalanceallowance
         *
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @param {string} [$params->asset_type] asset type => 'COLLATERAL' (default) or 'CONDITIONAL'
         * @param {string} [$params->token_id] token ID, default => from options.defaultTokenId)
         * @param {int} [$params->signature_type] signature type (default => from options.signatureType or options.signatureTypes.EOA).
         * @return {array} a ~@link https://docs.ccxt.com/#/?id=$balance-structure $balance structure~
         */
        $this->load_markets();
        // Ensure API credentials are generated (lazy generation)
        $this->ensure_api_credentials($params);
        // Default asset_type to COLLATERAL if not provided
        $assetType = $this->safe_string($params, 'asset_type', 'COLLATERAL');
        $params['asset_type'] = $assetType;
        // Use signature_type from $params or fall back to options
        $signatureType = $this->get_signature_type($params);
        $request = array(
            'asset_type' => $assetType,
        );
        if ($signatureType !== null) {
            $request['signature_type'] = $signatureType;
        }
        $tokenId = $this->safe_string($params, 'token_id');
        if ($tokenId === null) {
            $defaultTokenId = $this->safe_string($this->options, 'defaultTokenId');
            if ($defaultTokenId !== null) {
                $request['token_id'] = $defaultTokenId;
            }
        } else {
            $request['token_id'] = $tokenId;
        }
        // Fetch $balance and $allowance from CLOB endpoint
        $clobResponse = $this->clob_private_get_balance_allowance($request);
        //
        //     {
        //         "balance" => "1000000",
        //         "allowance" => "0"
        //     }
        //
        $balance = $this->safe_string($clobResponse, 'balance');
        $allowance = $this->safe_string($clobResponse, 'allowance');
        $collateral = $this->safe_string($this->options, 'defaultCollateral', 'USDC');
        // Convert CLOB $balance and $allowance (6 decimals) to standard units
        $collateralTotalValue = null;
        $collateralUsedValue = null;
        $collateralFreeValue = null;
        if ($balance !== null) {
            $parsedBalance = $this->parse_number($balance);
            if ($parsedBalance !== null) {
                $collateralTotalValue = $parsedBalance / 1000000;
            }
        }
        if ($allowance !== null) {
            $parsedAllowance = $this->parse_number($allowance);
            if ($parsedAllowance !== null) {
                $collateralUsedValue = $parsedAllowance / 1000000;
            }
        }
        // Calculate free $balance => total - used ($allowance)
        if ($collateralTotalValue !== null && $collateralUsedValue !== null) {
            $collateralFreeValue = $collateralTotalValue - $collateralUsedValue;
        } elseif ($collateralTotalValue !== null) {
            $collateralFreeValue = $collateralTotalValue;
        }
        $result = array(
            'info' => $clobResponse,
        );
        if ($collateralTotalValue !== null) {
            $account = $this->account();
            $account['total'] = $collateralTotalValue;
            if ($collateralFreeValue !== null) {
                $account['free'] = $collateralFreeValue;
            }
            if ($collateralUsedValue !== null) {
                $account['used'] = $collateralUsedValue;
            }
            $result[$collateral] = $account;
        }
        return $this->safe_balance($result);
    }

