         */
        $market = $this->safe_value($params, 'market');
        if ($market === null) {
            throw new ArgumentsRequired($this->id . ' dataPublicGetOpenInterest() requires a $market parameter');
        }
        // Convert $market to array if it's a single string
        $marketArray => stringarray() = array();
        if ((gettype($market) === 'array' && array_keys($market) === array_keys(array_keys($market)))) {
            $marketArray = $market;
        } elseif (gettype($market) === 'string') {
            $marketArray = array( $market );
        } else {
            throw new ArgumentsRequired($this->id . ' dataPublicGetOpenInterest() requires $market to be a string or array of condition IDs');
        }
        // API expects $market in query $params
        $requestParams = $this->extend(array( 'market' => $marketArray ), $this->omit($params, 'market'));
        return $this->request('oi', array( 'data', 'public' ), 'GET', $this->extend(array( 'api_type' => 'data' ), $requestParams));
