    public function create_deposit_address(string $code, $params = array ()) {
        /**
         * create a deposit $address for bridging assets to Polymarket
         *
         * @see https://docs.polymarket.com/developers/misc-endpoints/bridge-deposit
         *
         * @param {string} $code unified $currency $code
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @param {string} [$params->address] Polymarket wallet $address (required if not set in options)
         * @return {array} an ~@link https://docs.ccxt.com/#/?id=$address-structure $address structure~
         */
        // Get $address from $params or use default from options
        $address = $this->safe_string($params, 'address');
        if ($address === null) {
            // Try to get from options or throw error
            $address = $this->safe_string($this->options, 'address');
            if ($address === null) {
                throw new ArgumentsRequired($this->id . ' createDepositAddress() requires an $address parameter or $address in options');
            }
        }
        $response = $this->bridge_public_post_deposit($this->extend(array( 'address' => $address ), $params));
        // Response format => array($address => "...", $depositAddresses => [array(chainId, chainName, tokenAddress, $tokenSymbol, $depositAddress), ...])
        $depositAddresses = $this->safe_list($response, 'depositAddresses', array());
        // Find the deposit $address for the requested $currency $code
        // For Polymarket, all deposits are converted to USDC.e, but we can filter by $tokenSymbol
        $currency = $this->currency($code);
        $depositAddress = null;
        for ($i = 0; $i < count($depositAddresses); $i++) {
            $addr = $depositAddresses[$i];
            $tokenSymbol = $this->safe_string($addr, 'tokenSymbol');
            if ($tokenSymbol && strtoupper($tokenSymbol) === strtoupper($currency['code'])) {
                $depositAddress = $this->safe_string($addr, 'depositAddress');
                break;
            }
        }
        // If not found, return the first deposit $address (default to USDC)
        if ($depositAddress === null && strlen($depositAddresses) > 0) {
            $depositAddress = $this->safe_string($depositAddresses[0], 'depositAddress');
        }
        return array(
            'currency' => $code,
            'address' => $depositAddress,
            'tag' => null,
            'info' => $response,
        );
    }

