         *
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @param {Array} [$params->requests] array of array(token_id, limit?) objects (required)
         * @return {array} response from the exchange
         */
        $requests = $this->safe_value($params, 'requests');
        if ($requests === null || (gettype($requests) !== 'array' || array_keys($requests) !== array_keys(array_keys($requests))) || strlen($requests) === 0) {
            throw new ArgumentsRequired($this->id . ' clobPublicPostBooks() requires a $requests parameter (array of array(token_id, limit?) objects)');
        }
        // Note => REST API endpoint format => POST /books with JSON $body
        // See https://docs.polymarket.com/api-reference/orderbook/get-multiple-order-books-summaries-by-request
        // Request $body => [array(token_id => "..."), array(token_id => "...", limit => 10), ...]
        // Response format => array of order book objects, each with asset_id, bids, asks, etc.
        $body = $this->json($requests);
        $remainingParams = $this->extend(array( 'api_type' => 'clob' ), $this->omit($params, 'requests'));
