         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @param {string} [$params->order_id] the order ID (required)
         * @param {string} [$params->token_id] the token ID (required)
         * @param {string} [$params->side] the side => 'BUY' or 'SELL' (required)
         * @param {string} [$params->price] the price (required)
         * @param {string} [$params->size] the size (required)
         * @return {array} response from the exchange
         */
        // GET /order-scoring?order_id=...
        return $this->request('order-scoring', array( 'clob', 'private' ), 'GET', $this->extend(array( 'api_type' => 'clob' ), $params));
    }

    public function clob_private_post_are_orders_scoring($params = array ()) {
        /**
         * checks if multiple orders are currently scoring
         *
         * @see https://github.com/Polymarket/py-clob-client/blob/main/py_clob_client/endpoints.py (ARE_ORDERS_SCORING = "/are-orders-scoring")
         *
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @param {string[]} [$params->orderIds] array of order IDs to check (required)
         * @return {array} response from the exchange
         */
        $orderIds = $this->safe_value_2($params, 'orderIds', 'order_ids');
        if ($orderIds === null || (gettype($orderIds) !== 'array' || array_keys($orderIds) !== array_keys(array_keys($orderIds)))) {
            throw new ArgumentsRequired($this->id . ' clobPrivatePostAreOrdersScoring() requires an $orderIds parameter (array of order IDs)');
        }
        $body = $this->json(array( 'orderIds' => $orderIds ));
        $remainingParams = $this->extend(array( 'api_type' => 'clob' ), $this->omit($params, array( 'orderIds', 'order_ids' )));
        // POST /orders-scoring with JSON $body array( $orderIds => [...] )
        return $this->request('orders-scoring', array( 'clob', 'private' ), 'POST', $remainingParams, null, $body);
    }

    public function get_main_wallet_address() {
        /**
         * gets main wallet address (walletAddress or options.funder)
         * @return {string} main wallet address
         */
        if ($this->walletAddress !== null && $this->walletAddress !== '') {
            return $this->walletAddress;
        }
        $funder = $this->safe_string($this->options, 'funder');
        if ($funder !== null && $funder !== '') {
            return $funder;
        }
        throw new ArgumentsRequired($this->id . ' getMainWalletAddress() requires a wallet address. Set `walletAddress` or `options.funder`.');
    }

    public function get_proxy_wallet_address() {
        /**
         * gets proxy wallet address for Data-API endpoints (falls back to main wallet if not set)
         * @return {string} proxy wallet address
         */
        if ($this->uid !== null && $this->uid !== '') {
            return $this->uid;
        }
        $proxyWallet = $this->safe_string($this->options, 'proxyWallet');
        if ($proxyWallet !== null && $proxyWallet !== '') {
            return $proxyWallet;
        }
        // Fall back to main wallet if $proxyWallet is not set
        return $this->get_main_wallet_address();
    }

