        return $this->get_main_wallet_address();
    }

    public function get_user_total_value(?string $userAddress = null): array {
        /**
         * fetches total value of a user's positions from Data-API
         *
         * @see https://docs.polymarket.com/api-reference/core/get-total-value-of-a-users-positions
         *
         * @param {string} [$userAddress] user wallet $address (defaults to getProxyWalletAddress())
         * @return {array} object with 'value' (number) and 'response' (raw API response)
         */
        $address = null;
        if ($userAddress !== null) {
            // Use provided $address directly (public endpoint, no wallet setup needed)
            $address = $userAddress;
        } else {
            // Try to get proxy wallet $address, but handle case where wallet is not configured
            // This allows public calls without requiring wallet setup
            try {
                $address = $this->get_proxy_wallet_address();
            } catch (Exception $e) {
                // If wallet is not configured, require $userAddress parameter for public calls
                throw new ArgumentsRequired($this->id . ' getUserTotalValue() requires a $userAddress parameter when wallet is not configured. This is a public endpoint that can query any user $address->');
            }
        }
        // Fetch total value from Data-API
        $valueResponse = $this->data_public_get_total_value(array( 'user' => $address ));
        // Response format => [array("user" => "0x...", "value" => 123)]
        $valueData = $valueResponse;
        if ((gettype($valueResponse) === 'array' && array_keys($valueResponse) === array_keys(array_keys($valueResponse)))) {
            if (strlen($valueResponse) > 0) {
                $valueData = $valueResponse[0];
            } else {
                $valueData = array();
            }
        }
        $totalValue = $this->safe_number($valueData, 'value', 0);
        return array(
            'value' => $totalValue,
            'response' => $valueResponse,
        );
    }

