    public function parse_user_activity(array $activity, ?array $market = null): array {
        /**
         * parse a raw user $activity record into a trade-like structure consumable by parseTrades
         * @param {array} $activity raw $activity payload from Data-API
         * @param {array} [$market] $market structure, when known
         * @return {array|null} normalized $activity (only for TRADE records) or null
         */
        $activityType = $this->safe_string($activity, 'type');
        if ($activityType !== 'TRADE') {
            return null;
        }
        $rawTs = $this->safe_integer($activity, 'timestamp');
        $isoTimestamp = $this->safe_string($activity, 'timestamp');
        if ($rawTs !== null) {
            $tsMs = ($rawTs < 1000000000000) ? $rawTs * 1000 : $rawTs;
            $isoTimestamp = $this->iso8601($tsMs);
        }
        $symbol = ($market !== null) ? $market['symbol'] : $this->safe_string($activity, 'condition_id');
        return $this->extend($activity, array(
            'timestamp' => $isoTimestamp,
            'transactionHash' => $this->safe_string($activity, 'transactionHash'),
            'symbol' => $symbol,
            'asset' => $this->safe_string($activity, 'asset'),
            'price' => $this->safe_number($activity, 'price'),
            'size' => $this->safe_number($activity, 'size'),
            'side' => $this->safe_string($activity, 'side'),
        ));
    }

    public function format_address(?string $address = null) {
        if ($address === null) {
            return null;
        }
        if (str_starts_with($address, '0x')) {
            return str_replace('0x', '', $address);
        }
        return $address;
    }

    public function normalize_address(string $address): string {
        $normalized = trim('strval' ($address));
        if (str_starts_with(!$normalized, '0x')) {
            $normalized = '0x' . $normalized;
        }
        return strtolower($normalized);
    }

    public function hash_message(string $message): string {
        $binaryMessage = $this->encode($message);
        $binaryMessageLength = $this->binary_length($binaryMessage);
        $x19 = $this->base16_to_binary('19');
        $newline = $this->base16_to_binary('0a');
        $prefix = $this->binary_concat($x19, $this->encode('Ethereum Signed Message:'), $newline, $this->encode($this->number_to_string($binaryMessageLength)));
        return '0x' . $this->hash($this->binary_concat($prefix, $binaryMessage), 'keccak', 'hex');
    }

    public function get_contract_config(float $chainID): array {
        $contracts = $this->safe_value($this->options, 'contracts', array());
        $chainIdStr = (string) $chainID;
        $contractConfig = $this->safe_value($contracts, $chainIdStr);
        if ($contractConfig === null) {
            throw new ExchangeError($this->id . ' getContractConfig() invalid network chainId => ' . $chainIdStr);
        }
        return $contractConfig;
    }

    public function sign_message(string $message, string $privateKey): string {
        $hash = $this->hash_message($message);
        return $this->sign_hash($hash, $privateKey);
    }

    public function sign_hash(string $hash, string $privateKey) {
        $signature = $this->ecdsa(mb_substr($hash, -64), mb_substr($privateKey, -64), 'secp256k1', null);
        $r = $signature['r'];
        $s = $signature['s'];
        $v = $this->int_to_base16($this->sum(27, $signature['v']));
        // Convert to lowercase hex (Ethereum standard)
        $finalSignature strtolower(= ('0x' . str_pad($r, 64, '0', STR_PAD_LEFT) . str_pad($s, 64, '0', STR_PAD_LEFT) . str_pad($v, 2, '0', STR_PAD_LEFT)));
        return $finalSignature;
    }

    public function sign_typed_data(array $domain, array $types, array $value): string {
        // This returns binary data => 0x1901 || hashDomain($domain) || hashStruct(primaryType, $types, $value)
        $encoded = $this->eth_encode_structured_data($domain, $types, $value);
        // Hash the $encoded binary data with keccak256
        $hash = '0x' . $this->hash($encoded, 'keccak', 'hex');
        // Sign the $hash using signHash
        $signature = $this->sign_hash($hash, $this->privateKey);
        return $signature;
    }

    public function create_level1_headers(string $walletAddress, ?float $nonce = null): array {
        if ($walletAddress === null || $walletAddress === '') {
            throw new ArgumentsRequired($this->id . ' createLevel1Headers() requires a valid walletAddress');
        }
        $normalizedAddress = $this->normalize_address($walletAddress);
        $chainId = $this->safe_integer($this->options, 'chainId');
        $timestampSeconds = (int) floor($this->milliseconds() / 1000);
        $timestamp = (string) $timestampSeconds;
        $nonceValue = 0;
        if ($nonce !== null) {
            $nonceValue = $nonce;
        }
        $clobDomainName = $this->safe_string($this->options, 'clobDomainName');
        $clobVersion = $this->safe_string($this->options, 'clobVersion');
        $msgToSign = $this->safe_string($this->options, 'msgToSign');
        $domain = array(
            'name' => $clobDomainName,
            'version' => $clobVersion,
            'chainId' => $chainId,
        );
        // https://github.com/Polymarket/clob-client/blob/b75aec68be17190215b7230372fbedfe85de20ef/src/signing/eip712.ts#L28
        $types = array(
            'ClobAuth' => array(
                array( 'name' => 'address', 'type' => 'address' ),
                array( 'name' => 'timestamp', 'type' => 'string' ),
                array( 'name' => 'nonce', 'type' => 'uint256' ),
                array( 'name' => 'message', 'type' => 'string' ),
            ),
        );
        $message = array(
            'address' => $normalizedAddress,
            'timestamp' => $timestamp,
            'nonce' => $nonceValue,
            'message' => $msgToSign,
        );
        $signature = $this->sign_typed_data($domain, $types, $message);
        $headers = array(
            'POLY_ADDRESS' => $normalizedAddress,
            'POLY_TIMESTAMP' => $timestamp,
            'POLY_NONCE' => (string) $nonceValue,
            'POLY_SIGNATURE' => $signature,
        );
        return $headers;
    }

    public function get_clob_base_url($params = array ()): string {
        /**
         * Gets the CLOB API base URL (handles sandbox mode and custom hosts)
         * @param {array} [$params] extra parameters
         * @return {string} base URL for CLOB API
         */
        $apiType = $this->safe_string($params, 'api_type', 'clob');
        $baseUrl = $this->urls['api'][$apiType];
        // Check for sandbox mode
        if ($this->isSandboxModeEnabled && $this->urls['test'] && $this->urls['test'][$apiType]) {
            $baseUrl = $this->urls['test'][$apiType];
        }
        if ($apiType === 'clob') {
            $customHost = $this->safe_string($this->options, 'clobHost');
            if ($customHost !== null) {
                $baseUrl = $customHost;
            }
        }
        return $baseUrl;
    }

    public function parse_api_credentials(mixed $response): array {
        /**
         * Parses API $credentials from API $response and caches them
         * @param {array} $response API $response
         * @return {array} API $credentials array($apiKey, $secret, $passphrase)
         */
        $apiKey = $this->safe_string($response, 'apiKey') || $this->safe_string($response, 'api_key');
        $secret = $this->safe_string($response, 'secret');
        $passphrase = $this->safe_string($response, 'passphrase');
        if (!$apiKey || !$secret || !$passphrase) {
            throw new ExchangeError($this->id . ' parseApiCredentials() failed to parse $credentials-> Response => ' . $this->json($response));
        }
        $credentials = array(
            'apiKey' => $apiKey,
            'secret' => $secret,
            'passphrase' => $passphrase,
        );
        // Cache $credentials in options
        $this->options['apiCredentials'] = $credentials;
        // Also set them properties for use in sign() method
        $this->apiKey = $apiKey;
        $this->secret = $secret;
        $this->password = $passphrase;
        return $credentials;
    }

    public function create_api_key($params = array ()): array {
        /**
         * Creates a new CLOB API key for the given address
         *
         * @see https://github.com/Polymarket/py-clob-client/blob/main/py_clob_client/client.py
         * @see https://docs.polymarket.com/developers/CLOB/authentication
         *
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @param {number} [$params->nonce] optional nonce/timestamp
         * @return {array} API credentials array(apiKey, secret, passphrase)
         * @note Uses manual URL building instead of $this->request() because this endpoint requires L1 authentication
         * (POLY_ADDRESS, POLY_SIGNATURE $headers) rather than the standard L2 authentication used by $this->request()
         */
        if ($this->privateKey === null) {
            throw new ArgumentsRequired($this->id . ' create_api_key() requires a privateKey');
        }
        // Validate privateKey format (should be hex string with 0x prefix, 66 chars total)
        if (str_starts_with(!$this->privateKey, '0x') || strlen($this->privateKey) !== 66) {
            throw new ArgumentsRequired($this->id . ' create_api_key() requires a valid privateKey (0x-prefixed hex string, 66 characters)');
        }
        $walletAddress = $this->get_main_wallet_address();
        // Validate $walletAddress format (should be hex string with 0x prefix, 42 chars total)
        if (str_starts_with(!$walletAddress, '0x') || strlen($walletAddress) !== 42) {
            throw new ArgumentsRequired($this->id . ' create_api_key() requires a valid $walletAddress (0x-prefixed hex string, 42 characters). Got => ' . $walletAddress);
        }
        $baseUrl = $this->get_clob_base_url($params);
        $nonce = $this->safe_integer($params, 'nonce');
        $headers = $this->create_level1_headers($walletAddress, $nonce);
        $url = $baseUrl . '/auth/api-key';
        // POST /auth/api-key (creates new API credentials with L1 authentication)
        $response = $this->fetch($url, 'POST', $headers, null);
        return $this->parse_api_credentials($response);
    }

    public function derive_api_key($params = array ()): array {
        /**
         * Derives an already existing CLOB API key for the given address and $nonce
         *
         * @see https://github.com/Polymarket/py-clob-client/blob/main/py_clob_client/client.py
         * @see https://docs.polymarket.com/developers/CLOB/authentication
         *
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @param {number} [$params->nonce] optional nonce/timestamp
         * @return {array} API credentials array(apiKey, secret, passphrase)
         * @note Uses manual URL building instead of $this->request() because this endpoint requires L1 authentication
         * (POLY_ADDRESS, POLY_SIGNATURE $headers) rather than the standard L2 authentication used by $this->request()
         */
        if ($this->privateKey === null) {
            throw new ArgumentsRequired($this->id . ' derive_api_key() requires a privateKey');
        }
        $walletAddress = $this->get_main_wallet_address();
        $baseUrl = $this->get_clob_base_url($params);
        $nonce = $this->safe_integer($params, 'nonce');
        $headers = $this->create_level1_headers($walletAddress, $nonce);
        $url = $baseUrl . '/auth/derive-api-key';
        // GET /auth/derive-api-key (derives existing API credentials with L1 authentication)
        $response = $this->fetch($url, 'GET', $headers, null);
        return $this->parse_api_credentials($response);
    }

    public function create_or_derive_api_creds($params = array ()): array {
        /**
         * Creates API creds if not already created for nonce, otherwise derives them
         *
         * @see https://github.com/Polymarket/py-clob-client/blob/main/py_clob_client/client.py
         *
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @param {number} [$params->nonce] optional nonce/timestamp
         * @return {array} API credentials array(apiKey, secret, passphrase)
         */
        // Check if credentials are already cached
        $cachedCreds = $this->safe_dict($this->options, 'apiCredentials');
        if ($cachedCreds !== null) {
            return $cachedCreds;
        }
        // Try create_api_key first, then derive_api_key if create fails
        // Based on py-clob-client client.py => create_or_derive_api_creds()
        try {
            return $this->create_api_key($params);
        } catch (Exception $e) {
            // If create fails ($e->g., key already exists), try to derive it
            return $this->derive_api_key($params);
        }
    }

    public function set_api_creds(array $credentials) {
        /**
         * Sets API $credentials (alias for caching $credentials)
         *
         * @see https://github.com/Polymarket/py-clob-client/blob/main/py_clob_client/client.py
         *
         * @param {array} $credentials API $credentials array(apiKey, secret, passphrase)
         */
        $this->options['apiCredentials'] = $credentials;
        $this->apiKey = $this->safe_string($credentials, 'apiKey');
        $this->secret = $this->safe_string($credentials, 'secret');
        $this->password = $this->safe_string($credentials, 'passphrase');
    }

    public function get_api_base_url($params = array ()): string {
        /**
         * Gets the API base URL for the specified API type (handles sandbox mode and custom hosts)
         * @param {array} [$params] extra parameters
         * @param {string} [$params->api_type] API type ('clob', 'gamma', 'data', etc.)
         * @return {string} base URL for the API
         */
        $apiType = $this->safe_string($params, 'api_type', 'clob');
        // Ensure urls.api exists
        if ($this->urls === null || $this->urls['api'] === null) {
            throw new ExchangeError($this->id . ' getApiBaseUrl() failed => urls.api is not initialized. Make sure exchange is properly initialized.');
        }
        // Direct access to nested object property
        $baseUrl = $this->urls['api'][$apiType];
        // Check for sandbox mode
        if ($this->isSandboxModeEnabled && $this->urls['test'] && $this->urls['test'][$apiType]) {
            $baseUrl = $this->urls['test'][$apiType];
        }
        // Allow custom CLOB host override
        if ($apiType === 'clob') {
            $customHost = $this->safe_string($this->options, 'clobHost');
            if ($customHost !== null) {
                $baseUrl = $customHost;
            }
        }
        // Ensure we have a valid base URL
        if ($baseUrl === null) {
            $apiUrls = $this->urls['api'] || array();
            $availableTypesList = is_array($apiUrls) ? array_keys($apiUrls) : array();
            $availableTypes = '';
            if (strlen($availableTypesList) > 0) {
                $availableTypes = implode(', ', $availableTypesList);
            }
            throw new ExchangeError($this->id . ' getApiBaseUrl() failed => API type "' . $apiType . '" not found in urls.api. Available types => ' . $availableTypes);
        }
        return $baseUrl;
    }

    public function build_default_headers(string $method, ?array $existingHeaders = null): array {
        /**
         * Builds default HTTP $headers based on py-clob-client helpers.py
         *
         * @see https://github.com/Polymarket/py-clob-client/blob/main/py_clob_client/http_helpers/helpers.py
         *
         * @param {string} $method HTTP $method ('GET', 'POST', etc.)
         * @param {array} [$existingHeaders] existing $headers to extend
         * @return {array} $headers dictionary
         */
        if ($existingHeaders === null) {
            $existingHeaders = array();
        }
        $headers = $this->extend(array(
            'User-Agent' => 'ccxt',
            'Accept' => '*/*',
            'Connection' => 'keep-alive',
            'Content-Type' => 'application/json',
        ), $existingHeaders);
        // Add Accept-Encoding for GET requests (as per py-clob-client)
        if ($method === 'GET') {
            $headers['Accept-Encoding'] = 'gzip';
        }
        return $headers;
    }

    public function build_public_request(string $baseUrl, string $pathWithParams, string $method, array $queryParams, ?string $body = null, ?array $headers = null): array {
        /**
         * Builds a public (unauthenticated) request
         * @param {string} $baseUrl API base URL
         * @param {string} $pathWithParams path with parameters
         * @param {string} $method HTTP $method
         * @param {array} $queryParams query parameters
         * @param {string} [$body] request $body
         * @param {array} [$headers] request $headers
         * @return {array} request object with $url, $method, $body, and $headers
         */
        $headers = $this->build_default_headers($method, $headers);
        $url = $baseUrl . '/' . $pathWithParams;
        if ($method === 'GET') {
            if ($queryParams) {
                $url .= '?' . $this->urlencode($queryParams);
            }
        } else {
            // For POST requests, $body should already be set by the calling $method
            if ($body === null && $queryParams) {
                $body = $this->json($queryParams);
            }
        }
        return array( 'url' => $url, 'method' => $method, 'body' => $body, 'headers' => $headers );
    }

    public function ensure_api_credentials($params = array ()): array {
        /**
         * Ensures API credentials are generated (lazy generation, similar to dYdX's retrieveCredentials)
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @return {array} API credentials array(apiKey, secret, passphrase)
         */
        // Check if credentials are already cached
        $cachedCreds = $this->safe_dict($this->options, 'apiCredentials');
        if ($cachedCreds !== null) {
            return $cachedCreds;
        }
        // Check if credentials are provided directly (apiKey, secret, password)
        // This allows users to provide credentials directly instead of generating from privateKey
        if ($this->apiKey && $this->secret && $this->password) {
            $directCreds = array(
                'apiKey' => $this->apiKey,
                'secret' => $this->secret,
                'passphrase' => $this->password,
            );
            $this->set_api_creds($directCreds);
            return $directCreds;
        }
        // If direct credentials not provided, check if privateKey is available for generation
        if ($this->privateKey === null) {
            throw new ArgumentsRequired($this->id . ' ensureApiCredentials() requires either => (1) apiKey . secret . password provided directly, or (2) privateKey to generate credentials');
        }
        // Generate credentials lazily (similar to dYdX's retrieveCredentials pattern)
        // This is called automatically before authenticated requests
        $creds = $this->create_or_derive_api_creds($params);
        $this->set_api_creds($creds);
        return $creds;
    }

    public function get_api_credentials(): array {
        /**
         * Gets API credentials from cache or instance properties
         * @return {array} API credentials array($apiKey, $secret, $password)
         */
        $apiKey = $this->apiKey;
        $secret = $this->secret;
        $password = $this->password;
        // Check if credentials are already cached
        $cachedCreds = $this->safe_dict($this->options, 'apiCredentials');
        if ($cachedCreds !== null) {
            $apiKey = $this->safe_string($cachedCreds, 'apiKey') || $apiKey;
            $secret = $this->safe_string($cachedCreds, 'secret') || $secret;
            $password = $this->safe_string($cachedCreds, 'passphrase') || $password;
        }
        // If credentials are not available, check if privateKey is set
        // Only throw error if privateKey is set (meaning user wants authenticated requests)
        // This allows public requests to work even when privateKey is set but credentials not yet generated
        if (!$apiKey || !$secret || !$password) {
            if ($this->privateKey === null) {
                // No privateKey set - this should not happen if called from buildPrivateRequest
                throw new ArgumentsRequired($this->id . ' getApiCredentials() called but no credentials available and no privateKey set. This should only be called for authenticated requests. Provide either => (1) $apiKey . $secret . $password directly, or (2) privateKey to generate credentials.');
            }
            // privateKey is set but credentials not generated yet - this is expected for lazy generation
            // Don't throw error here, $ensureApiCredentials() handle it
            throw new ArgumentsRequired($this->id . ' API credentials not generated. Credentials are automatically generated on first authenticated request, but privateKey is required. Alternatively, provide $apiKey . $secret . $password directly.');
        }
        return array( 'apiKey' => $apiKey, 'secret' => $secret, 'password' => $password );
    }

    public function build_request_path_and_payload(string $pathWithParams, string $method, array $queryParams, ?string $body = null): array {
        /**
         * Builds the request path and $payload for signature
         * @param {string} $pathWithParams path with parameters
         * @param {string} $method HTTP $method
         * @param {array} $queryParams query parameters
         * @param {string} [$body] request $body
         * @return {array} array($requestPath, $url, $payload, $body)
         */
        // Ensure path doesn't have double slashes ($pathWithParams may already start with /)
        $normalizedPath = str_starts_with($pathWithParams, '/') ? $pathWithParams : '/' . $pathWithParams;
        $requestPath = $normalizedPath;
        $url = $requestPath;
        $payload = '';
        if ($method === 'GET') {
            if ($queryParams) {
                $queryString = $this->urlencode($queryParams);
                $url .= '?' . $queryString;
                $payload = $queryString;
            }
        } else {
            // For POST/PUT/DELETE, $body is part of the signature
            // Use deterministic JSON serialization (no spaces, compact) matching py-clob-client
            // json.dumps($body, separators=(",", ":"), ensure_ascii=False) produces compact JSON
            if ($body === null && $queryParams) {
                // json_encode by default produces compact JSON (no spaces)
                $body = json_encode ($queryParams);
            }
            // Serialize $body deterministically if it's an object
            if ($body !== null && gettype($body) === 'array') {
                $body = json_encode ($body);
            }
            // Use $body (quote replacement happens in createLevel2Signature)
            $payload = ($body !== null && $body !== '') ? 'strval' ($body) : '';
        }
        return array( 'requestPath' => $requestPath, 'url' => $url, 'payload' => $payload, 'body' => $body );
    }

    public function create_level2_signature(string $timestamp, string $method, string $requestPath, string $body, string $secret): string {
        /**
         * Creates Level 2 authentication signature (HMAC-SHA256)
         *
         * @see https://docs.polymarket.com/developers/CLOB/authentication
         *
         * @param {string} $timestamp timestamp string
         * @param {string} $method HTTP $method
         * @param {string} $requestPath request path
         * @param {string} $body request $body (serialized JSON string)
         * @param {string} $secret API $secret (base64 encoded, URL-safe)
         * @return {string} URL-safe base64 encoded signature
         */
        // Create signature => HMAC-SHA256($timestamp . $method . path . $body, $secret)
        // Based on Polymarket CLOB API L2 authentication (matches py-clob-client build_hmac_signature)
        // Use 'strval'($method) to preserve case (don't use toUpperCase())
        $message = 'strval' ($timestamp) . 'strval' ($method) . 'strval' ($requestPath);
        // Only add $body if it exists and is not empty
        // NOTE => Replace single quotes with double quotes (matching py-clob-client behavior)
        // This is necessary to generate the same hmac $message and typescript
        $messageWithBody = $message;
        if ($body !== null && $body !== '') {
            $messageWithBody = $message . str_replace("'", '"', 'strval' ($body));
        }
        // Generate HMAC and return URL-safe base64
        // Convert URL-safe base64 to standard base64 (replace - with . and _ with /)
        $secretBinary = str_replace('_', '/', base64_decode('strval' ($secret).replaceAll ('-', '+')));
        $hmacResult = $this->hmac($this->encode($messageWithBody), $secretBinary, 'sha256', 'base64');
        return str_replace('/', '_', $hmacResult->replaceAll ('+', '-'));
    }

    public function create_level2_headers(string $apiKey, string $timestamp, string $signature, string $password): array {
        /**
         * Creates Level 2 authentication headers
         *
         * @see https://github.com/Polymarket/py-clob-client/blob/main/py_clob_client/headers/headers.py
         *
         * @param {string} $apiKey API key
         * @param {string} $timestamp timestamp string
         * @param {string} $signature signature string
         * @param {string} $password API passphrase
         * @return {array} Level 2 headers dictionary
         */
        $authHeaders = array(
            'POLY_API_KEY' => $apiKey,
            'POLY_TIMESTAMP' => $timestamp,
            'POLY_SIGNATURE' => $signature,
            'POLY_PASSPHRASE' => $password, // Passphrase is required for L2 authentication
            'Content-Type' => 'application/json',
        );
        // Always include POLY_ADDRESS in Level 2 headers (matches GitHub issue #190 fix)
        // Get wallet address from funder option, $walletAddress property, or derive from privateKey
        $walletAddress = $this->safe_string($this->options, 'funder');
        if ($walletAddress === null && $this->walletAddress !== null) {
            $walletAddress = $this->walletAddress;
        }
        if ($walletAddress === null && $this->privateKey !== null) {
            // Derive wallet address from private key if not provided
            $walletAddress = $this->get_main_wallet_address();
        }
        if ($walletAddress !== null) {
            // Normalize and checksum the address (EIP-55)
            $walletAddress = $this->normalize_address($walletAddress);
            $authHeaders['POLY_ADDRESS'] = $walletAddress;
        }
        // // Add $signature type if provided (defaults to EOA from options)
        // $signatureType = $this->get_signature_type(params);
        // $eoaSignatureType = $this->safe_integer($this->safe_dict($this->options, 'signatureTypes', array()), 'EOA', 0);
        // if ($signatureType !== $eoaSignatureType) {
        //     $authHeaders['POLY_SIGNATURE_TYPE'] = (string) $signatureType;
        // }
        // // Add chain ID (defaults to 137 for Polygon mainnet, 80001 for testnet)
        // // chain_id => 137 = Polygon mainnet (default), 80001 = Polygon Mumbai testnet
        // $chainId = $this->safe_integer($this->options, 'chainId', 137);
        // $authHeaders['POLY_CHAIN_ID'] = (string) $chainId;
        return $authHeaders;
    }

    public function build_private_request(string $baseUrl, string $pathWithParams, string $method, array $queryParams, ?string $body = null, ?array $headers = null): array {
        /**
         * Builds a private (authenticated) request with L2 authentication
         * @param {string} $baseUrl API base URL
         * @param {string} $pathWithParams path with parameters
         * @param {string} $method HTTP $method
         * @param {array} $queryParams query parameters
         * @param {string} [$body] request $body
         * @param {array} [$headers] existing $headers
         * @return {array} request object with url, $method, $body, and $headers
         */
        // Ensure privateKey is set
        if ($this->privateKey === null) {
            throw new ArgumentsRequired($this->id . ' requires privateKey for authenticated requests');
        }
        // Get API credentials - this will throw if credentials not generated
        // For lazy generation, ensureApiCredentials() should be called before this
        $creds = $this->get_api_credentials();
        $timestamp = (string) $this->nonce();
        // Serialize $body deterministically if it's an object (matching py-clob-client)
        // Use json_encode which produces compact JSON by default (no spaces)
        // This matches => json.dumps($body, separators=(",", ":"), ensure_ascii=False)
        $serializedBody = null;
        if ($body !== null) {
            if (gettype($body) === 'array') {
                // Deterministic JSON => compact format (no spaces)
                $serializedBody = json_encode ($body);
            } else {
                $serializedBody = 'strval' ($body);
            }
        } elseif ($queryParams && ($method === 'POST' || $method === 'PUT' || $method === 'DELETE')) {
            // If $body is null but we have $queryParams for POST/PUT/DELETE, serialize them
            $serializedBody = json_encode ($queryParams);
        }
        // Build request path and payload using the serialized $body
        $pathAndPayload = $this->build_request_path_and_payload($pathWithParams, $method, $queryParams, $serializedBody);
        $requestPath = $pathAndPayload['requestPath'];
        $requestUrl = $pathAndPayload['url'];
        // Use the serialized $body for the actual request (exact string that will be sent)
        $finalBody = $serializedBody !== null ? $serializedBody : $pathAndPayload['body'];
        $privateUrl = $baseUrl . $requestUrl;
        // Create Level 2 $signature => for GET requests, do NOT include query params in $signature
        // For POST/PUT/DELETE, include the serialized $body (not query params)
        // This matches py-clob-client => $signature = $timestamp . $method . $requestPath [+ $body for non-GET]
        $bodyForSignature = ($method === 'GET') ? null : $serializedBody;
        $signature = $this->create_level2_signature($timestamp, $method, $requestPath, $bodyForSignature, $creds['secret']);
        // Create Level 2 $headers
        $authHeaders = $this->create_level2_headers($creds['apiKey'], $timestamp, $signature, $creds['password']);
        // Merge with existing $headers
        $headers = $this->build_default_headers($method, $headers);
        $headers = $this->extend($headers, $authHeaders);
        return array( 'url' => $privateUrl, 'method' => $method, 'body' => $finalBody, 'headers' => $headers );
    }

    public function sign($path, mixed $api = [ 'clob', $'public' ], $method = 'GET', $params = array (), $headers = null, $body = null) {
        /**
         * Signs a request for authenticated endpoints
         *
         * @see https://docs.polymarket.com/developers/CLOB/authentication
         *
         * @param {string} $path API endpoint $path
         * @param {string} $api API type ('public' or 'private')
         * @param {string} $method HTTP $method ('GET', 'POST', etc.)
         * @param {array} $params Request parameters
         * @param {array} $headers Request $headers
         * @param {string} $body Request $body
         * @return {array} Signed request with url, $method, $body, and $headers
         */
        // Get API base URL
        $baseUrl = $this->get_api_base_url($params);
        // Build $path with parameters
        $pathWithParams = $this->implode_params($path, $params);
        $query = $this->omit($params, $this->extract_params($path));
        // Remove api_type from $query params's not part of the actual API request
        $queryParams = $this->omit($query, array( 'api_type' ));
        // For public endpoints, no authentication needed
        // $api is always an array like ['gamma', 'public'] or ['clob', 'private']
        // The second element is the access level (public/private)
        $accessLevel = $this->safe_string($api, 1, 'public');
        if ($accessLevel === 'public') {
            return $this->build_public_request($baseUrl, $pathWithParams, $method, $queryParams, $body, $headers);
        }
        // For private endpoints, use L2 authentication
        return $this->build_private_request($baseUrl, $pathWithParams, $method, $queryParams, $body, $headers);
    }

    public function handle_errors(int $code, string $reason, string $url, string $method, array $headers, string $body, mixed $response, mixed $requestHeaders, mixed $requestBody) {
        if ($response === null) {
            return null;
        }
        // Polymarket API errors
        if ($code >= 400) {
            // Explicitly check for 401 (Unauthorized) and throw AuthenticationError
            if ($code === 401) {
                $authFeedback = $this->id . ' ' . $method . ' ' . $url . ' 401 ' . $reason . ' ' . $body;
                throw new AuthenticationError($authFeedback);
            }
            // Try to parse error message from $response first (can be JSON or text)
            // Check error message BEFORE status $code to catch specific errors like "Order not found"
            // that may return 400 status but should throw OrderNotFound instead of BadRequest
            $errorMessage = null;
            $errorData = null;
            try {
                if (gettype($response) === 'string') {
                    $errorMessage = $response;
                } elseif (gettype($response) === 'array') {
                    $errorMessage = $this->safe_string($response, 'error');
                    if ($errorMessage === null) {
                        $errorMessage = $this->safe_string($response, 'message');
                    }
                    if ($errorMessage === null) {
                        // If no error/message field, use the whole $response data
                        $errorData = $response;
                    }
                }
            } catch (Exception $e) {
                $errorMessage = $body;
            }
            $feedback = $this->id . ' ' . ($errorMessage || $body);
            if ($errorMessage !== null) {
                // Try exact match first ($e->g., "Order not found" -> '\\ccxt\\OrderNotFound')
                $this->throw_exactly_matched_exception($this->exceptions['exact'], $errorMessage, $feedback);
                // Then try broad match
                $this->throw_broadly_matched_exception($this->exceptions['broad'], $errorMessage, $feedback);
                // If no match, fall through to status $code check
            }
            // Check HTTP status $code (use throwExactlyMatchedException for proper type handling)
            // This handles cases where no specific error message is found in the $response
            $codeAsString = (string) $code;
            $statusCodeFeedback = $this->id . ' ' . $method . ' ' . $url . ' ' . $codeAsString . ' ' . $reason . ' ' . $body;
            $this->throw_exactly_matched_exception($this->exceptions['exact'], $codeAsString, $statusCodeFeedback);
            // If we reach here, no exception was thrown, so throw a generic error
            if ($errorData !== null) {
                throw new ExchangeError($this->id . ' ' . $this->json($errorData));
            } else {
                throw new ExchangeError($feedback);
            }
        }
        return null;
    }
}
